INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('늑대', '위협, 배신', '가축,물리다,죽다', '뜻하지 않는 권력가의 도움으로 어려운 일이 성사될 것을 예시한다.'),
                                                                                   ('늑대', '위협, 배신', '사람,변하다', '평소에 믿고 의지하던 사람으로부터 심한 배신을 당하게 될 것을 암시한다.'),
                                                                                   ('늑대', '위협, 배신', '노려보다', '타인으로부터 비판을 받거나 구설수에 휘말리게 된다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('토끼', '순수, 불안', '덫,걸리다,발버둥', '현재 속해 있는 모임이나 단체가 마음에 들지 않아 탈퇴하고 싶지만 눈치만 보고 있음을 나타낸다. 결단력 있게 행동해야 한다.'),
                                                                                   ('토끼', '순수, 불안', '실험,갇히다', '논문이나 연구에서 성과를 나타내고 인정받게 될 예시이다. 간혹 교통사고에 대한 예시일 수 있으므로 각별히 주의해야 한다.'),
                                                                                   ('토끼', '순수, 불안', '새끼,낳다', '수입이 늘어나고 재물이 들어와 쌓일 징조이다. 창작, 예술 계통 종사자라면 작품을 발표하여 인정받게 된다.'),
                                                                                   ('토끼', '순수, 불안', '산,놀다,떼', '장차 무수한 정객들을 거느린 위대한 정치가가 될 것이다.'),
                                                                                   ('토끼', '순수, 불안', '달아나,숨다', '현재 추진하고 있는 일의 목표가 분명치 못해 혼란을 겪고 있다. 계획을 재검토하고 명확한 목표를 세울 필요가 있다.'),
                                                                                   ('토끼', '순수, 불안', '맹수,쫓기다', '부하직원이 사표를 내거나 애인이 변심하게 될 꿈이다. 대인관계가 불안정해지며 직장이나 부서를 옮기는 변화가 예상된다.'),
                                                                                   ('토끼', '순수, 불안', '방,들어오다,앉다', '집안에 근심이나 우환이 생길 징조이다. 당분간 마음이 심란할 징조이다.'),
                                                                                   ('토끼', '순수, 불안', '하늘,올라가다', '운이 상승하여 재물이 들어오고 일이 잘 풀리며 집 안에 경사가 겹칠 길몽이다. 승진하거나 취직하게 되고 귀인을 만나 신분이 상승하게 된다.'),
                                                                                   ('토끼', '순수, 불안', '풀밭,놀다,평화', '가정이 안정되고 직장에서 입지도 안정된다. 위기의 상황은 모두 지나가고 평화로운 나날이 기다리고 있다.'),
                                                                                   ('토끼', '순수, 불안', '나오다,탈출', '고용인이 나가려고 하지만 붙잡을 일이 있을 것이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('여우', '교활, 유혹, 구설수', '일반', '교활한 동물로 좋지 않은 소문, 구설수, 이득 없는 권위를 상징한다. 대인관계에서 손해를 볼 수 있으므로 주의를 요한다.'),
                                                                                   ('여우', '교활, 유혹, 구설수', '꿩,뒤쫓다', '생각지 못한 다른 사람을 만나 실속 없이 시간을 보내게 될 징조이다.'),
                                                                                   ('여우', '교활, 유혹, 구설수', '동굴,숲,어둡다,놀라다', '자신이 잘 모르던 사람으로 인해 불안한 일이 생길 것을 예견하는 꿈이다.'),
                                                                                   ('여우', '교활, 유혹, 구설수', '울음소리,듣다,밤', '불길한 소식을 듣게 되거나 천재지변이 닥쳐올 것을 예시하는 꿈이다.'),
                                                                                   ('여우', '교활, 유혹, 구설수', '산,잡다', '학교나 관청에서 명예나 권세가 주어지게 될 것을 예시한다.'),
                                                                                   ('여우', '교활, 유혹, 구설수', '닭,물다', '교활하고 진꾀에 능수능란한 사람에게 당하게 된다.'),
                                                                                   ('여우', '교활, 유혹, 구설수', '죽이다', '생각지도 않았던 곳에서 큰 돈을 벌게 될 것이다.'),
                                                                                   ('여우', '교활, 유혹, 구설수', '먹이,굴,들어가다', '자신에게 들어온 복을 다른 사람에게 빼앗기는 꿈이다.'),
                                                                                   ('여우', '교활, 유혹, 구설수', '사육하다', '남성의 경우 여자를 주의하여야 할 징조이고 주변의 교활한 사람을 만나게 될 것을 예시한다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('곰', '권력, 재물, 풍요', '일반', '권력자, 실력자, 단체의 장, 힘 있는 세력, 권력, 재물을 상징하며 앞으로 삶이 풍요롭게 될 것을 암시하는 꿈이다.'),
                                                                                   ('곰', '권력, 재물, 풍요', '죽이다,웅담', '국가고시에서 합격하거나 사업이 크게 성공을 거두어 사람들의 주목을 받게 될 것이다.'),
                                                                                   ('곰', '권력, 재물, 풍요', '타다,길', '어떤 정당의 당수, 공공기관이나 단체의 우두머리 등이 된다.'),
                                                                                   ('곰', '권력, 재물, 풍요', '나무,오르다,헤엄', '자신이나 가족 중 한 사람이 출세하거나 승진하여 권리를 행사할 일이 있을 것이다.'),
                                                                                   ('곰', '권력, 재물, 풍요', '집,들어오다,아수라장', '어머니의 간섭으로부터 벗어나고 싶다는 욕구가 이런 꿈으로 나타난 것이다. 윗사람의 시달림으로부터 벗어나고자 하는 심리를 나타낸 것이다.'),
                                                                                   ('곰', '권력, 재물, 풍요', '집,어슬렁거리다', '정신적으로 어머니에게 집착하고 있거나 독립하지 못했음을 나타내는 꿈이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('고양이', '여성, 비밀, 불안', '일반', '여성성의 동물로서 앙칼진 여자, 감시자, 경비원, 자신의 본성에 숨겨진 비밀, 질병, 불륜 등을 상징한다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '검다,울다,쫓아오다', '답답하고 불안한 일을 겪게 될 것이다. 울음소리가 사방에 울렸다면 불길한 소문이 돌게 될 것이다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '높다,오르다', '직장에서 승진하여 고위 간부가 된다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '웅크리다,앉다', '재물을 축내려는 사람이 생기거나 고용인을 감시하고 보호해주어야 함을 암시한다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '땅,파다,묻다', '어떤 사실을 감추고 있는 데 대한 불안한 마음이 반영된 꿈이다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '말하다', '고양이가 현실의 누군가와 동일할 경우가 많다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '발목,휘감다', '음모에 휘말릴 수 있으므로 언행에 특별히 조심하고 감언이설에 넘어가지 않도록 마음의 중심을 잡는 것이 중요하다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '방,숨다,들어오다', '사기를 당하거나 도둑이 들거나 재물이 빠져나가게 된다. 가족 중 병에 걸리거나 사고를 당하는 사람이 있을 수도 있다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '할퀴다', '아내 혹은 남편으로 인해 체면이 깎이거나 명예에 먹칠을 할 일이 있을 것이다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '쥐,잡다', '본인이나 가족 중 누군가가 재물을 얻게 될 것이다. 골칫거리를 누군가 나서서 대신 해결해주게 될 것이다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '죽이다,벽,시멘트', '어떤 범죄에 가담하거나 연루될 것을 암시한다. 입장을 분명히 하고 단호한 행동을 취하도록 해야 한다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '죽이다', '위기 상황에서 극적으로 벗어나게 된다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '물리다,고통', '자신에게 유리한 권리나 지위가 주어지게 된다. 피가 나는 꿈이었다면 명예훼손을 당하거나 병에 시달리게 된다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '개,싸우다', '경쟁자와 알력 다툼이 일어나게 된다. 이성적으로 판단하여 처리할 것.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '눈빛,빛나다', '어떤 사람의 작품에 크게 감동을 받거나 자신의 창작물이 여러 사람들에게 감동을 주게 될 것이다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '닭장,들여다보다', '자신에게 손해를 끼칠 인물이 나타나게 된다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '기르다,사다', '비밀을 갖게 된다. 기혼 남자의 경우 정부가 생기게 된다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '밖,나가다', '고용인을 해고하게 될 일이 있을 것이다. 혹은 중요한 물건을 잃어버릴 수도 있다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '안다,놀다', '남성이 이런 꿈을 꾸면 여성으로 인해 난처한 입장에 놓이게 되고 매우 벅차고 골치 아픈 일이 생기게 된다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '안아주다,어루만지다', '여성이나 어린아이를 품에 안을 일이 생기거나 자신에게 벅차고 고달픈 일이 생기게 될 것을 예시한다.'),
                                                                                   ('고양이', '여성, 비밀, 불안', '호랑이,착각', '잔뜩 기대를 걸었던 일이나 사람이 알고 보니 별 볼일 없는 사람이거나 실속 없는 일이라는 것을 알게 된다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('호랑이', '권력, 명예, 재물', '일반', '경쟁자, 근심거리, 재물, 배우자, 직장동료, 명예 등을 상징하는 것으로 태몽으로 풀이하는 경우도 있다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '울음소리,도망,숨다', '구설수에 오르거나 재산을 잃게 되며 신상에 변고가 생길 수도 있다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '꼬리,잘리다', '자신의 뜻을 크게 펼치지 못하는 안 좋은 일이 일어날 수 있다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '늙다,힘없다', '실제로 권력과 지위를 잃게 되고 심신이 고달플 것을 암시한다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '다치다,피,돌보다', '귀인이 나타나 어려움으로부터 구해줄 암시이다. 이를 계기로 운이 트이고 사업이 번창하게 된다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '동물원,보다', '관공서나 공공기관의 관리나 그에 상응하는 사람의 도움을 받게 되고 성공하게 된다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '타다,달리다', '유명인이나 위대한 사람의 도움을 받아 귀하게 될 것이다. 미혼 여성이 이런 꿈을 꾸면 훌륭한 배우자를 만나게 된다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '싸우다,이기다', '장차 사업에 크게 성공하게 될 것이다. 혹은 권력의 중심부로 들어갈 수도 있다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '길,열어주다,눈빛', '어떤 기관이나 회사 조직체 내에서 사업이나 학문에 깊숙이 관여하게 된다. 결국에는 권세를 잡거나 협조적인 인물을 만나 만사형통하게 된다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '원숭이,그리다', '사회적으로 유명해질 암시이다. 부귀와 공명을 거머쥐고 정치에 참여할 운도 트인다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '머리,변하다', '꿈속에서 머리가 호랑이로 변한 그 사람에게 최고의 영예가 내릴 암시이다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '짐승,잡아먹다', '경쟁자를 물리치고 자신이 승리자가 될 것을 예시하는 꿈이다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '초원,놀다,많다', '주위에 많은 인재들이 있어 그들의 도움을 받게 된다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '꽃밭,업다,집', '명예로운 사람이나 단체의 힘을 얻어 높은 지위로 나아가 고위층 관리가 되거나 정치가가 될 것을 예시한다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '토끼,커지다', '작은 일부터 시작하여 점차 번창하게 된다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '가죽,털,얻다', '자신과 뜻이 같은 협조자를 만나게 되고 재물과 권력 등을 얻게 된다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '도망,발,떨다', '앞으로 벅찬 일이 닥쳐 고통을 당하거나 권력자에게 심적 고통을 당하게 된다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '방,들어오다', '귀인이 찾아오거나 훌륭한 작품 또는 일거리를 얻게 될 수도 있다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '따라다니다,출몰', '어려운 상황에서 협조자를 얻거나 사업이 잘 추진되어 크게 성공한다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '포효,울부짖다', '높은 자리에 오르게 되며 명예와 부귀영화를 누리게 될 꿈이다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '얌전,앉다', '많은 사람들을 지배하는 자리에 오르게 된다. 높은 지위에 올라 지도력을 발휘하게 될 것을 암시한다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '문앞,웅크리다', '크게 성공하여 사람들에게 널리 이름이 알려지며 명성과 명예 등을 쌓게 될 것이다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '집,쑥대밭', '주변의 모함으로 인해 큰 손실을 입고 곤경에 처할 암시이며 직장상사의 횡포로 극심한 고통을 겪는다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '집,지키다', '권세와 명예를 가진 사람이 자신을 후원해 줄 일이 있거나 최대의 권세, 명예, 재물운을 획득하게 된다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '쫓다,울타리,발,물다', '누군가 사나운 사람이 시비를 걸어올 일이 있음을 예시한다. 시비 끝에 자신이 다치게 된다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '하늘,울부짖다', '국가에 중대한 변고가 생길 조짐이다. 개인적으로는 시험에 낙방하거나 사업이 내리막길을 향하게 될 조짐이다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '물리다,상처', '권력을 잡게 되거나 직장에서 진급한다. 사업가라면 사업체가, 예술가라면 작품이 크게 성공하여 명예나 권세를 얻게 된다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '끌다', '많은 사람들을 마음대로 움직이게 되고 큰 일을 성사시키게 된다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '죽이다', '돈과 명예, 지위와 사업운을 잃게 된다. 협조자가 손을 떼게 되며 사업상의 거래나 계약이 취소되어 피해를 볼 징조이다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '타다,내리다', '높은 지위에서 물러나거나 불명예스러운 일로 명예가 훼손된다. 좋지 않은 자리로 좌천당하게 된다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '타다,대궐,들어가다', '협조자나 정당, 단체 등의 추대를 받아 큰 기관이나 단체의 우두머리로 출세하게 된다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '쫓기다,도망', '운이 기울어 장애를 만나 재물을 놓치게 된다. 문제를 해결하기 어렵다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '성교하다', '사업가라면 큰 사업을 시작하게 되고, 예술가라면 훌륭한 작품이 만들어지거나 권력층과 동업을 하게 된다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '등,타다,달리다', '권력과 돈을 함께 쥐게 되며 출세의 대 길몽이다.'),
                                                                                   ('호랑이', '권력, 명예, 재물', '물리다', '행운이 따를 꿈이다. 금전과 자원을 얻고 소원을 성취하게 된다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('말', '교통, 협조자, 후원자', '일반', '교통수단, 대인관계, 가족, 친지, 협조자, 후원자를 상징한다. 직장에서는 아랫사람을 의미한다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '검다,집,날뛰다', '검은 말이 집 안으로 뛰어들어와 난동을 부렸다면 어떤 충격으로 인해 몸과 마음이 황폐해질 것을 암시한다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '경마장,관람', '뜻이 맞는 동업자나 좋은 파트너를 만나게 될 징조이다. 복권 당첨이 암시되며 각종 경쟁에서 유리한 위치를 차지하게 된다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '날개,공중,날다', '어떤 분야에서든 성공하게 됨을 의미한다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '얻다,집,끌다', '협력자의 도움으로 사업이 크게 번성하여 큰 돈을 벌게 된다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '달리다,쓰러지다', '일이 잘 돼나가다가 뜻하지 않은 역경을 만나 끝내 좌절하고 만다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '뜰,춤', '집에 화재가 날 징조이다. 각별히 조심해야 한다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '흩어지다,달아나다', '그동안 쌓아온 재산이 흩어져 없어지게 되고 추진하는 일이 제대로 풀리지 않는다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '묶이다,울다', '현재 하고 있는 일에 위험이 다가오고 있음을 알려주는 꿈이다. 동료나 동업자의 실수나 방해로 인해 일이 실패로 끝날 수 있으므로 주의를 요한다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '수레,짐,싣다', '좋지 않은 일로 인해 이사를 하는 등의 환경 변화가 생긴다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '물리다', '어떤 단체나 세력에서 자신을 끌어가기 위해 접촉해 올 것이다. 장차 관직에 앉게 되거나 세력을 잡게 될 수도 있다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '타다,질주,들판', '하고자 하는 일이 순조롭게 진행되며 소원을 이루게 된다. 길몽 중 길몽이다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '타다,떨어지다', '야망에 부풀어 전심전력을 다하다가 중도에 장애에 부딪혀 좌절하게 된다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '타다,산,오르다', '신분 상승을 의미한다. 사회 단체의 추대를 받아 권력을 얻거나 진급, 승진 등을 하게 된다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '타다,장가', '취직을 하거나 승진을 하게 되고 금전적, 신분상의 상승이 있게 된다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '성기', '믿고 아껴주었던 아랫사람이 자기에게 반항하거나 배신하게 된다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '발,구르다,울음소리', '자신의 노력으로 한 일이 남의 손으로 전해지게 된다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '수레,수렁,빠지다', '갑작스러운 고난과 깊은 좌절을 하게 되는 것을 암시한다. 사업가라면 사업이 침체되거나 몰락하게 된다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '야성,달리다', '활발하고 씩씩한 성격의 아들을 낳을 꿈이다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '짐,줄어들다', '자신을 짓누르고 있는 문제가 점차 해결되어 간다는 의미이다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '백마,문밖,타다', '관직으로 나아가 입신 출세하게 되며 재물과 명예를 얻을 암시이다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '미혼,여자,타다', '천생연분의 남성을 만나 훌륭한 결혼을 하게 될 징조이다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '백마,하늘,날다,내려오다', '사업이나 추진 중인 일이 크게 성공하는 듯하다가 내리막길을 걷게 될 것을 예시하는 꿈이다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '안장,야생,달리다', '야망은 있으나 현실적으로 이루어지기 힘든 야망이어서 매우 위태롭게 진행되고 있음을 보여준다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '안장없다,목적지,도착', '모든 여건이 따라주지 않는데도 오로지 자신의 집념과 노력만으로 큰 성공을 이루어내게 된다.'),
                                                                                   ('말', '교통, 협조자, 후원자', '조상,가족,끌다', '집 안에 며느리나 가정부, 일하는 사람을 두게 될 것이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('개', '충성, 배신, 경고', '짖다,소리', '명예를 떨칠 일이 생긴다. 작가라면 작품이 베스트셀러가 되고 연예인이라면 인기가 급상승되는 등 자기 분야에서 일가견을 나타낼 길몽이다.'),
                                                                                   ('개', '충성, 배신, 경고', '두발,서다,걷다', '가까운 사람이 자기를 정면으로 공격하거나 자신이 다른 사람을 향해 인신공격하게 된다.'),
                                                                                   ('개', '충성, 배신, 경고', '높다,앉다', '훌륭한 지도자가 될 것을 예시한다.'),
                                                                                   ('개', '충성, 배신, 경고', '떼,덤벼들다', '뜻하지 않은 시비에 휘말리거나 신변에 위험이 생길 징조이니 조심해야 한다.'),
                                                                                   ('개', '충성, 배신, 경고', '마당,파다', '뜻밖의 행운이 찾아올 징조이다. 자신을 도와줄 협력자나 후원자가 생길 것을 암시하는 길몽이다.'),
                                                                                   ('개', '충성, 배신, 경고', '사납다,들어오다,못하다', '실제로도 방해에 부딪혀 난처한 입장에 처하게 된다.'),
                                                                                   ('개', '충성, 배신, 경고', '말하다', '아랫사람 중 누군가가 자신을 배반하거나 아랫사람에게 보증을 서 주었다가 큰 손해를 보게 된다.'),
                                                                                   ('개', '충성, 배신, 경고', '싸우다,보다', '잡병에 걸리거나 시비에 휘말릴 일이 있을 것이다.'),
                                                                                   ('개', '충성, 배신, 경고', '주인,물다', '가까운 사람에게 배신을 당해 큰 손해를 입게 된다.'),
                                                                                   ('개', '충성, 배신, 경고', '집,나가다', '재물이 손실되고 소망하던 일에서 좌절을 맛보게 된다.'),
                                                                                   ('개', '충성, 배신, 경고', '고기,먹다', '형제간 우애에 금이 갈 일이 생긴다. 부동산 거래 실패, 복잡한 사건에 연루되어 재물을 잃고 집안 살림이 궁핍해질 징조이다.'),
                                                                                   ('개', '충성, 배신, 경고', '끌다,다니다', '경비나 경호원 등의 일을 하게 되거나 학업에 정진하여 성과를 얻게 된다.'),
                                                                                   ('개', '충성, 배신, 경고', '안다,쓰다듬다', '자식이나 부하직원으로 인해 근심거리가 생기고 하는 일에서 난관을 겪게 된다.'),
                                                                                   ('개', '충성, 배신, 경고', '물리다,상처', '취직이 되거나 직장인인 경우 중책을 맡게 된다. 상처에서 피가 났다면 심복이나 고용인에게 배신을 당하게 된다.'),
                                                                                   ('개', '충성, 배신, 경고', '검다,마당,들어오다', '죽음과 사고의 위험이 따른다는 암시이며 위험한 유혹이나 음모에 속아넘어가는 것을 예지하는 흉몽이다.'),
                                                                                   ('개', '충성, 배신, 경고', '남의집,들어오다', '좋지 않은 소식을 듣게 되거나 자신에게 좋지 않은 영향을 끼칠 사람이 나타나게 된다.'),
                                                                                   ('개', '충성, 배신, 경고', '두마리,싸우다,피', '불편한 관계에 있는 사람과의 정면 충돌, 말다툼, 격렬한 싸움을 나타내므로 신상에 주의를 요한다.'),
                                                                                   ('개', '충성, 배신, 경고', '사납다,쫓기다', '아랫사람이나 친구로부터 배반을 당할 징조이다. 자신의 운세나 건강이 대단히 약해질 징조이기도 하다.'),
                                                                                   ('개', '충성, 배신, 경고', '흉하다,따라오다', '부랑아 등을 만나 낭패를 당하거나 전염병 등에 걸릴 수 있다.'),
                                                                                   ('개', '충성, 배신, 경고', '희다,마당,들어오다', '자신을 도와줄 동료가 생기거나 능력 있는 협조자가 나타나서 어려운 고비를 넘기게 해준다.'),
                                                                                   ('개', '충성, 배신, 경고', '떼,싸우다,여러마리', '소송이나 어떤 사건에 연루되어 시달리게 될 암시이다. 자신을 괴롭히는 문제가 점점 복잡해진다.'),
                                                                                   ('개', '충성, 배신, 경고', '강도,쫓다,구해주다', '협력자나 신의 깊은 친구의 도움으로 고비를 넘기고 재기하게 될 것을 예시한 꿈이다.'),
                                                                                   ('개', '충성, 배신, 경고', '새끼,낳다', '운세가 상승되고 경사가 겹칠 길몽이다. 가정적으로 풍요를 누린다.'),
                                                                                   ('개', '충성, 배신, 경고', '교미,보다', '사업에서 동업자가 나타나 어려운 고비를 넘기게 되고 계약은 목적한 대로 이루어진다.'),
                                                                                   ('개', '충성, 배신, 경고', '성기', '집안 식구 중 누군가가 자신에게 반항할 일이 생긴다.'),
                                                                                   ('개', '충성, 배신, 경고', '뒤꽁무니,따라다니다', '누군가에게 부탁한 일이 성사되지 않아 애를 태우다가 결국 제3자를 통해 해결을 보게 된다.'),
                                                                                   ('개', '충성, 배신, 경고', '자신,되다', '명예와 위신이 땅에 떨어지거나 지위를 잃고 처지가 몰락하게 될 것을 예시한다.'),
                                                                                   ('개', '충성, 배신, 경고', '죽이다', '어렵다고 여겨지던 일을 성사시키거나 고시 같은 어려운 시험에 합격하여 출세하게 된다.'),
                                                                                   ('개', '충성, 배신, 경고', '개집,들어가다', '현실의 위기를 이겨내고 성공하기 위해서는 좀더 대범해져야 한다는 경고의 꿈이다.'),
                                                                                   ('개', '충성, 배신, 경고', '강아지,풀어주다,대문', '한번 좋은 일이 있으면 한번은 근심스러운 일이 생기게 될 것이다.'),
                                                                                   ('개', '충성, 배신, 경고', '나가다,돌아오다', '위태로운 고비를 넘고 일이 순탄하게 풀리며 이득을 얻게 될 징조이다.'),
                                                                                   ('개', '충성, 배신, 경고', '죽다', '재산상으로 손해를 보고 믿고 의지하던 사람을 잃게 되는 등 곤경에 빠질 암시이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('나비', '변화, 사랑, 자유', '꽃,앉다,보다', '미혼인 경우 연애를 하게 되거나 혹은 반가운 사람을 만나기도 한다.'),
                                                                                   ('나비', '변화, 사랑, 자유', '잠자리,알,낳다,보다', '작가는 많은 소재로 이론을 정립하게 되어 새로운 이야기를 쓰게 되고, 사업가는 원래의 사업 외에 부수적으로 사업 성과를 얻게 되어 재물을 쌓게 된다.'),
                                                                                   ('나비', '변화, 사랑, 자유', '날아다니다,보다', '나비는 죽은 사람의 영혼을 상징하므로 주의를 요하는 꿈이다. 그러나 날아다니는 나비를 보며 낭만적인 기분에 빠지게 되면 사랑에 빠지고 싶다는 소망이 나타난 것으로 본다.'),
                                                                                   ('나비', '변화, 사랑, 자유', '여러마리,모이다,날아다니다,보다', '예상하지 못했던 경사가 생기게 됨을 예시한다.'),
                                                                                   ('나비', '변화, 사랑, 자유', '자신,되다,날아다니다,꿈찾다', '예술가인 경우에는 훌륭한 작품을 쓰거나 완성시키게 되며, 인기인이 되어 이름을 떨치게 된다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('용', '권력, 성공, 길조', '갯벌,머리,캐내다', '어느 단체나 기관, 사업체 등에서 우두머리가 되거나 권세를 얻게 됨을 예시한 것이다.'),
                                                                                   ('용', '권력, 성공, 길조', '맑다,물,노닐다,구경', '맑고 청결한 사상과 음률이 충만한 어떤 사업장에서 성공하여 명예와 권세가 항상 함께하게 된다.'),
                                                                                   ('용', '권력, 성공, 길조', '두마리,뒤엉기다,하늘,올라가다', '사업을 하는 사람이라면 뜻이 맞는 동업자를 구해보다 큰 규모로 하는 것이 좋다.'),
                                                                                   ('용', '권력, 성공, 길조', '두마리,마주보다,엉클어지다', '두 개의 세력 단체나 조직이 서로 의견 대립이 생겨 라이벌 관계에 놓이게 되는 꿈이다.'),
                                                                                   ('용', '권력, 성공, 길조', '불난집,하늘,솟아오르다', '사업이나 추진 중인 일이 크게 번성하여 세상에 과시하게 된다.'),
                                                                                   ('용', '권력, 성공, 길조', '상처,하늘,날다', '사업이나 추진하던 일, 소원 등을 이루게 되지만 자신의 뜻을 크게 펴보지는 못하게 된다.'),
                                                                                   ('용', '권력, 성공, 길조', '물건,변하다', '일생의 운세가 크게 변할 것이다.'),
                                                                                   ('용', '권력, 성공, 길조', '연못,잠자다', '실력과 능력이 있지만 아직 때를 만나지 못하고 있음을 상징한다.'),
                                                                                   ('용', '권력, 성공, 길조', '타다,산,올라가다', '성적이 크게 오르거나 사업이 크게 성공한다. 관직에 오르게 되어 자신이 바라던 일이 이루어지게 된다.'),
                                                                                   ('용', '권력, 성공, 길조', '타다,하늘,날다', '높은 고위직에 올라 만인을 지배할 입신 양명의 꿈이다.'),
                                                                                   ('용', '권력, 성공, 길조', '문장,조각,보다', '저명인사를 만나거나 그와 관계된 일을 하게 된다. 희귀한 물건이나 서적 등을 대하게 되어 도움을 받게 된다.'),
                                                                                   ('용', '권력, 성공, 길조', '입,불,뜨겁다', '권력 있는 사람의 도움을 받아 하는 일이 쉽게 풀리게 된다.'),
                                                                                   ('용', '권력, 성공, 길조', '허리,팔,끌어안다', '주문이 쇄도해 일이 많아지게 되고 사람이 모여들게 된다.'),
                                                                                   ('용', '권력, 성공, 길조', '공중,날다,울다,밀다', '추진하던 사업이나 학문적 업적 등으로 세상에 명성을 떨쳐 소문날 일이 생기게 된다.'),
                                                                                   ('용', '권력, 성공, 길조', '나뭇가지,걸리다', '감당하기에 벅찬 일을 맡아 힘겹게 된다. 주변 사람들의 부추김이나 감언이설에 넘어가지 않도록 주의를 요한다.'),
                                                                                   ('용', '권력, 성공, 길조', '날아가다,사라지다', '보살펴 주던 협조자가 멀어져 가거나 권세나 명예, 일 등이 한때 세상에 알려져 명성을 떨치지만 점점 그 힘을 잃게 됨을 예시한다.'),
                                                                                   ('용', '권력, 성공, 길조', '자신,멀어지다', '자신에게 더없이 좋은 기회를 놓치게 되고, 사업이나 추진하던 일 등이 점차 기울게 된다.'),
                                                                                   ('용', '권력, 성공, 길조', '자신,죽이다', '매우 불길한 암시이다. 심각한 재난을 당하고 범죄의 피해자가 되기 쉽다.'),
                                                                                   ('용', '권력, 성공, 길조', '태우다,날아가다', '좋은 일이 있을 것임을 예시해주고 있다. 사업이 크게 번성하고 재물이 쌓이며 학문적인 성과를 얻게 될 것을 예시하고 있다.'),
                                                                                   ('용', '권력, 성공, 길조', '하늘,소리,내다', '사업이나 정치 등에 성공을 하여 사람들이 우러러 보게 될 것이다.'),
                                                                                   ('용', '권력, 성공, 길조', '물,잠기다,보다', '어떤 기관에서 추진하다가 보류되어 있던 일에 관계하게 된다. 희귀하게 여겨지는 금은보화를 보게 된다.'),
                                                                                   ('용', '권력, 성공, 길조', '불,등,뜨겁다', '관청이나 높은 지위에 있는 사람의 도움을 받아 승진 또는 출세하게 되거나 사업이 번성하게 된다.'),
                                                                                   ('용', '권력, 성공, 길조', '사람,물다,죽이다,보다', '어떤 세력에 의해서 자신이 추진하던 일이나 사업 등이 성취되어 사람들에게 신용을 쌓게 된다.'),
                                                                                   ('용', '권력, 성공, 길조', '승천,보다', '많은 사람들을 좌지우지할 수 있는 자리에 오르게 된다.'),
                                                                                   ('용', '권력, 성공, 길조', '승천,바다,떨어지다', '지위와 재산을 잃게 될 것을 암시한다. 소송 문제에 연루되어 곤란을 겪을 징조이다.'),
                                                                                   ('용', '권력, 성공, 길조', '습격,맞붙다,싸우다', '자신이 훌륭하게 되기 위하여 노력하거나 벅찬 일거리를 성취시키려고 노력할 일이 있게 된다.'),
                                                                                   ('용', '권력, 성공, 길조', '자신,되다', '성공을 암시하는 꿈이며 대길몽이다. 부귀영화를 누리게 된다.'),
                                                                                   ('용', '권력, 성공, 길조', '쫓아오다,싸우다,물리다', '명예와 권력을 얻기 위해 고군분투할 것이며, 결국 권세를 잡게 될 것이다.'),
                                                                                   ('용', '권력, 성공, 길조', '하늘,꼬리,잡다,놓치다', '많은 반대를 부리치고 자신에게 도움이 되어줄 사람과 관계를 맺게 되어 그 사람의 도움을 받아 성공하게 된다.'),
                                                                                   ('용', '권력, 성공, 길조', '하늘,떨어지다,죽다', '일이 잘못되어 가산을 모두 탕진하게 된다. 그동안 애써 일으킨 기업도 파산하게 된다.'),
                                                                                   ('용', '권력, 성공, 길조', '하늘,집,날아들다', '가문이 흥하게 되고 이름을 만방에 떨칠 꿈이다.'),
                                                                                   ('용', '권력, 성공, 길조', '빛,해,올라가다,하늘', '새로운 사업을 시작하게 되며 그동안의 연구 성과나 노력이 관련 기관이나 사업체로부터 크게 평가를 받고 권세와 명예가 함께 주어져 크게 감격하게 됨을 예시한다.'),
                                                                                   ('용', '권력, 성공, 길조', '우물,백마,하늘,오르다', '사업이나 자기 일에 있어 승승장구하며, 훗날엔 더 큰 사업체를 운영하거나 더 훌륭한 업적을 이룩하여 크게 성공하게 된다.'),
                                                                                   ('용', '권력, 성공, 길조', '우물,들어가다,보다', '직장에서 승진을 하게 되거나 감옥에 들어가게 된다. 자신이 관계하고 있는 어느 기관에 의해 추진 중인 일이나 작품 등이 채택되기도 한다.'),
                                                                                   ('용', '권력, 성공, 길조', '자기,꽉,껴안다', '벅찬 일거리를 맡게 되거나 훌륭한 사람과 협조할 일이 생길 것이다.'),
                                                                                   ('용', '권력, 성공, 길조', '통째로,먹히다,뱃속,요동,피투성이', '세력가나 세력 집단, 기관 등에서 어떤 권리나 이권, 재물 등을 획득하게 될 것을 예시한다. 직장인이라면 승진을 하는 등 좋은 일이 일어날 것이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('뱀', '재물, 지혜, 위험', '누렇다,보다', '횡재수가 있거나 송사에 휘말리게 된다. 혹은 구설수에 휘말리게 되는 것을 암시한다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '문틈,여러마리,들어오다', '여성이라면 남자 복이 많아 앞으로 여러 남자들을 만날 수 있을 것이다. 남자가 이런 꿈을 꾸었다면 신변에 어떤 위험이 닥칠 것을 예시하는 것이다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '물리다,독,짜내다', '횡재수가 있어 복권 당첨 등의 일로 실현되는 경우도 있다. 혹은 사회사업을 크게 성공시키거나 재물을 얻게 된다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '물리다,독,온몸,퍼지다', '재물을 얻을 징조이다. 굵고 힘이 세보이는 뱀에게 물렸을수록 이득도 많아진다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '먹다', '현실에서 벅차다고 생각했던 어떤 일을 처리하게 되거나 새로운 학설, 작품 등을 끌어다 자기 것으로 소화시킬 일이 생긴다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '치마,써서,죽이다', '자식 중 누군가가 불의의 사고를 당할 수 있다. 조심해야 할 때다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '잡다,번뜩,놓치다', '들어오려던 재물이나 이득이 목전에서 사라져버릴 흉몽이다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '죽이다', '목적하던 바를 이루고 재산을 얻게 된다. 또한 자신에게 해가 되는 사람이나 세력을 제거하게 된다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '화살,쏘다,맞추다', '하는 일에 살수나 방해 없이 척척 맞아떨어지고 만사 형통한다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '몸통,안보이다,꼬리,보이다', '경쟁자와 크게 대립되는 관계에 놓이거나 자신의 뜻과는 다른 적대행위를 하는 단체의 지도자와 정면으로 싸우게 되는 상황에 놓이게 된다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '나무,밑,위,기어오르다', '매사가 순조롭게 풀릴 조짐이다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '나무,위,밑,기어내려가다', '매사에 장애와 막힘이 많아서 소원 성취가 어려울 흉몽이다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '똬리,틀다,혀,내름거리다,바라보다', '사업이나 추진 중인 일 등에 있어 상황이 악화되거나 음흉한 사람에게 피해를 입게 된다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '몸,감추다,턱밑,노려보다,무섭다,떨다', '가정적으로 불화가 이어져 가정이 깨질 수도 있다. 특히 남성의 경우 아내로 인해 자유를 구속받게 될 것이다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '몸,휘감기다,두렵지않다', '큰 돈이 들어오고 재산이 늘어날 징조로 길몽이다. 직장인은 승진운이 트인다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '자기,품,들어오다', '매우 재수가 좋은 꿈이다. 금전적인 이득과 이권을 얻어 사업이 날로 번창할 징조이다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '자기몸,감기다,턱밑,노려보다,떼내다', '가정이 불화를 겪거나 강제로 이혼을 하게 될 것이다. 그러나 뱀을 완전히 떼어내지 못한다면 별거를 하게 될 것이다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '물다,사라지다', '생각지도 못한 일로 아는 사람으로부터 마음에 상처를 받게 될 것이다. 또는 자신과 관련이 있는 어느 기관에 의하여 정신적으로 도움을 받아 어려운 상황을 극복하게 된다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '통째로,삼키다', '정신적인 균형이 무너져 판단력을 잃고 상대방의 기에 압도되거나 남의 속임수에 넘어가는 것을 의미한다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '칼,삼키다,보다', '공직에 나아가거나 승진을 하게 될 것이다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '도룡뇽,알,먹다', '큰 부와 명예를 얻게 된다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '숲,나무줄기,누워,위장', '음흉한 사람의 계략에 넘어갈 일이 생기거나 예상치 못한 일이 생겨 당황하게 된다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '살뱀,우글거리다', '어학 쪽으로 소질이 있는 딸을 낳게 될 것이다. 언론이나 동시통역사 등에 재능이 보일 것이다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '여러마리,문,들어오다', '여성이 이런 꿈을 꾸면 자기가 원하는 남성을 만나게 되고, 남성은 위험한 일이 생기게 된다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '몸,감기다,사라지다', '하는 일이 난관에 부딪치고 궁핍해질 징조이다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '입,나오다', '자신을 돌아볼 필요가 있음을 암시하는 꿈이다. 남을 험담, 비방하다가 오히려 자기가 곤경에 처하거나 망신을 당하게 될 우려가 있으므로 언행에 신중을 기하는 것이 좋겠다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '자기집,밖,나가다', '패가망신할 흉몽이다. 하는 일이 제대로 안되어 가산을 탕진하고 가난해지게 된다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '자신,삼기다', '권력과 강한 힘을 거머쥐게 될 것을 상징한다.'),
                                                                                   ('뱀', '재물, 지혜, 위험', '크다,쫓아오다,사람,변하다', '부담스럽거나 거추장스러운 일이라서 피하고 싶지만 어쩔 수 없이 그 일을 맡거나 수락해야만 할 일이 있을 것이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('까마귀', '불길, 죽음, 재난', '안방,들어오다', '집안에 도둑이 들거나 우환이 생길것을 암시한다. 질병, 악귀 등을 상징하는 꿈이다.'),
                                                                                   ('까마귀', '불길, 죽음, 재난', '떼,하늘,높이,날아오르다,보다', '자신의 일을 도와주던 귀인이나 협조자가 떠나거나 사국이나 주변 상황이 자신의 뜻과는 다르게 변화하게 된다. 또는 친척간에 불화가 생길 것이다.'),
                                                                                   ('까마귀', '불길, 죽음, 재난', '떼,하늘,빙빙,돌다,날다,보다', '친척끼리 불화할 일이 생기거나 사업 파트너, 후원자, 동업자 등 자기의 일에 도움을 주던 사람들이 하나하나 떨어져 나갈 것이다.'),
                                                                                   ('까마귀', '불길, 죽음, 재난', '까치,떼,동물,시체,창자,파먹다,보다', '사업이 번창하여 종업원이나 직원들을 더 많이 쓸 일이 생길 것이다. 혹은 집 안에서 큰 잔치를 벌여 많은 손님들을 대접할 일이 있을 것이다.'),
                                                                                   ('까마귀', '불길, 죽음, 재난', '울음소리,듣다', '까마귀는 병, 죽음, 재난 등을 상징한다. 또한 음모에 휘말려들 우려도 있다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('의사', '치료, 해결, 권위', '약,받다', '좋은 꿈이다. 어려운 일이 해결되고 여러 가지 면에서 운이 트일 징조이다. 당장은 어려움을 겪고 있더라도 조만간 해결이 가능하다.'),
                                                                                   ('의사', '치료, 해결, 권위', '병세,설명하다', '자신의 이력이나 사업 실적 등에 관해서 누군가에게 설명을 해주어야 할 일이 생길 것이다. 여기서 의사는 직장상사나 사업 파트너, 해당 관청의 담당자 등과 동일시된 인물일 수 있다.'),
                                                                                   ('의사', '치료, 해결, 권위', '진료,받다', '어려운 일이 해결되고 운세가 호전될 것을 보여주는 꿈이다.'),
                                                                                   ('의사', '치료, 해결, 권위', '약봉지,약병,건네받다', '이제까지의 어려운 일이 해결되고 여러 가지 면에서 운이 트일 징조이다. 당장은 어려움을 겪고 있더라도 조만간 해결이 가능하다.'),
                                                                                   ('의사', '치료, 해결, 권위', '눈,이상,안과,찾아가다', '이성적 판단력이나 통찰력이 흐려져 있어 혼란스러운 상태이므로 이런 꿈을 꾸고 난 후에는 될 수 있으면 중요한 결정을 내리지 않는 것이 좋다.'),
                                                                                   ('의사', '치료, 해결, 권위', '많다,머리,수술하다', '심사 기관이나 심사 위원들로부터 자신의 문예작품이나 논문, 학문적 연구물을 심사 받을 일이 있다.'),
                                                                                   ('의사', '치료, 해결, 권위', '약사,조제실,약,조제,보다', '건강에 이상이 있다는 신호로 받아들여야 한다.'),
                                                                                   ('의사', '치료, 해결, 권위', '파란약,받다', '건강에 대한 해결책을 얻게 되고 연구원이나 시험생에게는 좋은 결과와 합격의 행운을 얻는 것을 암시한다.'),
                                                                                   ('의사', '치료, 해결, 권위', '아프다,찾아,헤매다', '현실에서 어떤 곤란한 일에 대한 해결책을 찾기 위해 고민하고 있거나 자신의 인생에 대해 고민하고 있음을 나타내는 꿈이다.'),
                                                                                   ('의사', '치료, 해결, 권위', '화내다', '아버지나 선생님, 직장상사 등과 어떤 대립이 있거나 그들의 기대에 어긋나는 어떤 일로 인해 불안해하는 마음을 나타내고 있다.'),
                                                                                   ('의사', '치료, 해결, 권위', '진단서,병없다,진단', '많은 사람들의 비웃음을 사거나 구설수에 오르게 될 징조이므로 조심하는 것이 좋다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('연예인', '명예, 인기, 욕구', '장례행렬,민장,들고,행진,보다', '자신이 명성을 떨치게 되는 꿈. 상여 뒤를 따르는 행렬이 길면 길수록 명성이 드높아지고 자신을 따르는 사람이 많아짐을 뜻한다.'),
                                                                                   ('연예인', '명예, 인기, 욕구', 'TV,직접,배우,보다,의상,부러워하다', '자신의 주위에 있는 어떤 사람의 지위나 뛰어난 작품 등을 보고 자신과 비교하게 되고 패배의식을 갖게 된다.'),
                                                                                   ('연예인', '명예, 인기, 욕구', '관람석,앉다,가수,배우,말걸다,주목', '직장이라든가 자신이 속한 모임에서 특별한 존재로 인정받고 싶다는 소망이 꿈으로 나타난 것이다.'),
                                                                                   ('연예인', '명예, 인기, 욕구', '무대,화려,의상,가수,노래,보다', '자신의 성격이 내성적이라서 남들 앞에서 좀더 활발하고 자신 있는 성격이 되고 싶다는 욕구가 꿈으로 나타난 것이다.'),
                                                                                   ('연예인', '명예, 인기, 욕구', '배우,무대,깔깔,웃다', '현실에서 누군가에게 위축을 당하거나 패배의식을 느끼기 쉽다. 그러나 반대로 자신이 배우가 되어 호탕하게 웃는 꿈은 현실에서 자신이 많은 사람들을 압도하고 따르게 만들 일이 생길 것이다.'),
                                                                                   ('연예인', '명예, 인기, 욕구', '배우,무대,알몸,춤추다,바라보다', '배우와 동일시되는 어떤 사람이 자신의 신분이나 과거, 실수, 좌장 등을 하나하나 끄집어내면서 시비를 걸어올 일이 있을 징조이다.'),
                                                                                   ('연예인', '명예, 인기, 욕구', '영화,촬영장,구경꾼,많다,혼란', '자신의 사업이 여러 가지 점에서 보완하거나 고쳐야 할 일이 많이 생기게 되고 자신의 일에 관심을 갖고 있는 사람이 많음을 뜻한다.'),
                                                                                   ('연예인', '명예, 인기, 욕구', '유명,배우,옷,받다,입다', '평소 관심을 가지고 있던 분야의 유명한 인기인의 지도를 받거나 협조를 얻어 비슷한 일을 하게 된다.'),
                                                                                   ('연예인', '명예, 인기, 욕구', '유명,영화배우,탤런트,데이트', '직장이나 모임 등에서 인기를 얻거나 과시할 만한 일이 생긴다.'),
                                                                                   ('연예인', '명예, 인기, 욕구', '유명,탤런트,함께,걷다', '친구나 애인, 혹은 자신이 작업하고 있는 작품이나 이루고자 하는 꿈, 명예 등의 동일시이다.'),
                                                                                   ('연예인', '명예, 인기, 욕구', '자기집,영화,촬영,보다', '어떤 작품 활동을 하게 되거나 이와 관련된 직종에 종사하며 혹은 이러한 사람과 친분을 맺게 된다.'),
                                                                                   ('연예인', '명예, 인기, 욕구', '자신,유명,연인,키스,애무', '결혼한 사람이라면 현재 자신의 배우자 외에 다른 누군가를 마음에 두고 떳떳치 못한 생각이나 행동을 한 경우에 이런 꿈을 꾼다.'),
                                                                                   ('연예인', '명예, 인기, 욕구', '자신,유명,가수,무대,노래,박수갈채', '많은 사람들 앞에서 연설을 하거나 예술가인 경우 대중 앞에 공개하여 명성을 떨치게 된다.'),
                                                                                   ('연예인', '명예, 인기, 욕구', '자신,인기,가수,탤런트,환호,인터뷰', '자신이 처한 현실에 대한 강한 불만이 나타난 꿈이다. 자신을 알아주지 않거나 자신의 진가를 발휘할 수 있는 기회를 주지 않는 현실에 대한 불만이 클수록 꿈속에선 더욱더 화려한 대접을 받게 된다.'),
                                                                                   ('연예인', '명예, 인기, 욕구', '텅빈,각석,바라보다,무대,하얀,드레스,춤추다', '심리적인 소외와 외로움을 나타낸다.'),
                                                                                   ('연예인', '명예, 인기, 욕구', '군중,연설,유명인,악수', '별 실익도 없는 일에 휘말려 몸 고생 마음 고생을 하게 되거나 다른 사람에 막혀 사회 진출에 어려움이 생기게 된다.'),
                                                                                   ('연예인', '명예, 인기, 욕구', '여자,유명인,자기집,찾아오다', '어떤 보증서나 차용증서, 이권 등을 획득하게 될 것을 예시하며 명예와 권리가 주어진다.'),
                                                                                   ('연예인', '명예, 인기, 욕구', '유명인,성인,자신,집,찾아오다', '사업가는 사업이 번성하여 크게 재물을 쌓게 되며, 정치인은 높은 관직을 얻거나 큰 세력을 얻게 된다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('땀', '노력, 고통, 건강', '구슬,흘리다', '근면함을 발휘하여 대업을 쌓아 명예를 얻기도 하고, 때로는 한때 절제 없는 낭비로 집안이 기울기도 하는 것을 암시한다.'),
                                                                                   ('땀', '노력, 고통, 건강', '손바닥,뜨겁다', '강력한 힘이 솟아나고 하는 일마다 박력 있게 처리하게 된다.'),
                                                                                   ('땀', '노력, 고통, 건강', '안색,붉다,식은땀', '자신의 욕망이 소망이 너무 크고 강하여 건강을 해치게 되는 꿈으로 자신을 되돌아보는 것이 필요하다.'),
                                                                                   ('땀', '노력, 고통, 건강', '온몸,비오듯,흠뻑,젖다', '피와는 달리 땀으로 온몸이 젖어 있었던 꿈은 흉몽이다. 죽음이나 질병, 사고 등을 암시한다.'),
                                                                                   ('땀', '노력, 고통, 건강', '이마,땀방울,솟다,얼굴,흐르다', '사고를 당해 피를 흘릴 만큼 상처를 입거나 돈을 탕진하게 될 일이 있을 것이다.'),
                                                                                   ('땀', '노력, 고통, 건강', '이마,땀방울,송골송골,맺히다', '재물을 잃게 되거나 어떤 사고로 상처를 입게 될 것을 예시한다.'),
                                                                                   ('땀', '노력, 고통, 건강', '흐르다,말끔히,닦다', '뭔가 새로운 환경에 놓이게 되어 새롭게 일을 기획할 수 있게 되고 다시 예전의 기력과 재력을 회복하게 될 것이다.'),
                                                                                   ('땀', '노력, 고통, 건강', '콧등,식다,땀방울,맺히다', '사업을 하다 실패하게 된다. 기진맥진하는 꿈이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('머리', '정신, 지혜, 권위', '누군가,뒤통수,보다', '상대방이 자신의 의사를 잘 따르게 됨을 의미한다.'),
                                                                                   ('머리', '정신, 지혜, 권위', '칼,자르다,쫓아오다', '현실에서 추진하는 일이 좋은 성과를 거둘 때 거기에 대한 중요한 공로가 자기에게 돌아오게 되는 것을 의미한다.'),
                                                                                   ('머리', '정신, 지혜, 권위', '잘린,천장,매달다', '급하게 처리해야 할 일이 생기거나 다른 사람, 기관, 부서 등에 부탁할 일이 생길 것을 예시한다.'),
                                                                                   ('머리', '정신, 지혜, 권위', '땅,떨어지다,다치다', '새로운 일이나 새로운 계획, 새로운 사업을 시작하게 되거나 시작하라는 어떤 메시지이다.'),
                                                                                   ('머리', '정신, 지혜, 권위', '아프다,어지럽다,이마,손,짚다', '자신의 아이디어나 능력을 발휘해 큰 성취를 이룰 것을 예시한 꿈이다. 그러나 머리가 아프다는 것에 초점이 맞춰져서 뚜렷이 기억에 남는다면 뇌에 관계된 이상이 생겼을 수도 있다.'),
                                                                                   ('머리', '정신, 지혜, 권위', '다치다', '자신에게 어떤 충격이 올 것을 미리 암시한 꿈이라고 본다. 정신적인 충격을 받게 될 우환이 생길 수 있으므로 매사에 조심하는 것이 좋겠다.'),
                                                                                   ('머리', '정신, 지혜, 권위', '목,잘리다,몸통,떨어지다,보다,만지다', '꿈 내용은 끔찍하지만 해몽은 좋다. 오랫동안 골치를 썩이던 문제가 해결될 징조이다. 뜻밖의 행운을 잡게 된다. 기쁜 일이 이중으로 겹친다.'),
                                                                                   ('머리', '정신, 지혜, 권위', '자기,뿔,나다', '누군가에 대해 몹시 화가 나 있는 상태를 보여주는 꿈이다. 화로 자신을 상하게 할 수 있으니 우선 자기 마음을 다스릴 필요가 있다.'),
                                                                                   ('머리', '정신, 지혜, 권위', '대머리,불안', '직장이나 그 밖의 일 처리에 있어서 능력이 떨어지는 것에 대한 불안감을 나타내는 것이다.'),
                                                                                   ('머리', '정신, 지혜, 권위', '자신,몹시,작다,보이다', '자신의 일이 대수롭지 않게 생각되어 다른 사람에게 알리지 못하거나 다른 사람에게 알려질까 두려워하게 된다.'),
                                                                                   ('머리', '정신, 지혜, 권위', '용,사자,범,변하다', '고급 관리나 장성, 어떤 단체나 집단의 우두머리가 된다.'),
                                                                                   ('머리', '정신, 지혜, 권위', '찌그러지다,모양,보이다', '대인관계에 문제가 있을 수 있으니 자신의 성격이나 일의 추진 방식을 바꾸어야 한다.'),
                                                                                   ('머리', '정신, 지혜, 권위', '자신,누군가,뒤통수,때리다', '꿈속에 등장했던 인물이나 그가 상징하는 어떤 인물에 대한 모든 것을 들추어내게 되며 그에 대한 벌이나 탄핵 등이 쉬워진다.'),
                                                                                   ('머리', '정신, 지혜, 권위', '잘리다,동물,피,흐르다,보다', '추진하던 일이나 사업이 성취되어 막대한 재산을 얻게 된다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('심장', '감정, 사랑, 생명', '괴기영화,사람,요리,먹다', '꿈 내용은 끔찍하지만 실제로는 사랑의 열병에 빠지게 될 암시이며 그 사랑이 결실을 이루게 될 암시이다.'),
                                                                                   ('심장', '감정, 사랑, 생명', '숨,가쁘다,두근거리다', '마음이 급하여 온종일 분주하고 일이 많다. 질병이 생길 수 있고 구설수, 다툼 등이 생기게 될 것을 암시하는 꿈이다.'),
                                                                                   ('심장', '감정, 사랑, 생명', '터지다,진정,애쓰다', '미혼인 사람이 이런 꿈을 꾸었다면 곧 사랑의 열병을 앓게 될 예시이다. 실제로 가슴 두근거릴 만큼 좋은 일이 생기거나 깜짝 놀랄 일이 일어날 가능성이 높다.'),
                                                                                   ('심장', '감정, 사랑, 생명', '어떤사람,칼,찌르다', '당신의 경쟁자나 경쟁 사업체에 치명적인 타격을 주어 선발주자로 나서거나 승리하게 됨을 암시하는 꿈이다.'),
                                                                                   ('심장', '감정, 사랑, 생명', '자신,없어지다', '자신의 충실한 협조자나 친한 친구, 성실한 고용인 등 소중한 사람을 잃게 되거나 어떤 귀한 물건을 잃어버리게 된다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('몸', '건강, 자아, 노력', '강물,씻다,더러워지다', '열심히 일한 성과가 사라지거나 남으로부터 인정받지 못하게 되는 꿈이다.'),
                                                                                   ('몸', '건강, 자아, 노력', '혹,생기다', '재물과 관련하여 크게 이득이 생기며 사업이 번창하여 성공을 거두는 꿈이다.'),
                                                                                   ('몸', '건강, 자아, 노력', '술,취하다,제대로,가누다,못하다', '유행성 병에 걸리게 되거나 경쟁자의 꼬임에 빠져 그 잡념에서 벗어나기 어려울 것을 예시한다.'),
                                                                                   ('몸', '건강, 자아, 노력', '어깨,튼튼,단단,몸집', '탄탄한 기반 위에 운이 트이고 행운이 찾아올 꿈이다.'),
                                                                                   ('몸', '건강, 자아, 노력', '옷,흐트러지다,드러나다', '의지할 곳을 잃거나 유혹당할 일이 생긴다.'),
                                                                                   ('몸', '건강, 자아, 노력', '움직이다,살,쪄서,사람,볼까봐,숨다', '몸이 병적으로 살이 쪄 있는 꿈은 건강에 대해 너무 지나치게 염려하고 있다는 증거이다. 실제로 건강에 이상이 생길 수도 있으므로 건강 관리를 꾸준히 하면서 마음을 편히 가지도록 한다.'),
                                                                                   ('몸', '건강, 자아, 노력', '이,물어대다', '근심거리가 생길 징조이다.'),
                                                                                   ('몸', '건강, 자아, 노력', '자기,기아,난민,앙상,뼈,남다', '과로로 몸이 허약해지거나 격렬하고 힘든 운동이나 노동을 하고 나서 지쳐 있을 때 이런 꿈을 꾸게 된다.'),
                                                                                   ('몸', '건강, 자아, 노력', '자신,키작은,똥보,길거리,놀림거리', '업무상의 일에 있어서 권위를 가지게 되며 운세의 호전을 나타낸다. 건강 면에서도 상당히 양호하다는 것을 알려주는 꿈이다.'),
                                                                                   ('몸', '건강, 자아, 노력', '목,몹시,가늘어지다', '경제적으로 빈곤해지거나 처지가 곤궁해질 암시이다. 건강 면에서도 기력을 잃고 병에 걸리기 쉽다.'),
                                                                                   ('몸', '건강, 자아, 노력', '양말,목,조이다', '남성과 관련하여 성적인 욕망이나 소망을 상징한다.'),
                                                                                   ('몸', '건강, 자아, 노력', '어떤사람,목,송곳,찌르다', '감기나 편도선염에 걸리겠으니 조심해야겠다. 이런 꿈은 이미 감기나 편도선염에 걸린 상태에서 현실의 일이 꿈에 반영된 것이므로 감기나 편도선염이 더 심해져 목이 쉬게 될 것을 알려주는 것이다.'),
                                                                                   ('몸', '건강, 자아, 노력', '자신,목,다른사람,목마,타다', '누군가에게 심한 간섭을 받게 되거나 사업이나 일에 있어 자신보다 제3자가 공공연히 나서서 기분 상할 일이 생길 것을 예시한다.'),
                                                                                   ('몸', '건강, 자아, 노력', '자신,목,뚝,잘리다', '꿈의 내용과는 정반대의 해몽이다. 환경의 변화를 암시하는 꿈으로 행복한 미래가 펼쳐질 길몽이다.'),
                                                                                   ('몸', '건강, 자아, 노력', '자신,동물,목,잡다', '입학 시험, 고시, 승진 시험, 취직 시험 등에 우수한 성적으로 합격하게 될 것을 예시한다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('주방', '재물, 횡재, 생활', '먼곳,사람,여행,부엌,만나다', '조만간 소식을 듣게 되거나 혹은 떠난 사람이 돌아오게 될 귀환의 징조이다.'),
                                                                                   ('주방', '재물, 횡재, 생활', '음식,열심히,만들다', '진행중인 일을 재점검하거나 새로운 일을 모색해야 할 징조.'),
                                                                                   ('주방', '재물, 횡재, 생활', '물,마시다', '횡재수, 재물, 돈, 먹거리 등과 관련한 암시이다.'),
                                                                                   ('주방', '재물, 횡재, 생활', '반찬거리,가득,쌓이다', '자금이 없어 실행에 옮기지 못한 사업계획에 자금이 만들어지게 된다.'),
                                                                                   ('주방', '재물, 횡재, 생활', '살림,주방가구,소리,내다', '비방을 듣게 되거나 모함에 빠지거나 그로 인한 피해가 발생하게 된다.'),
                                                                                   ('주방', '재물, 횡재, 생활', '그릇,음식,가득,담기다', '집안에 고사나 잔치가 벌어진다. 파티, 모임, 재물, 돈, 물품 등이 생긴다.'),
                                                                                   ('주방', '재물, 횡재, 생활', '바닥,물,흘러가다', '횡재를 하거나 재물이 들어오게 될 좋은 꿈이다.'),
                                                                                   ('주방', '재물, 횡재, 생활', '관,들어가다', '횡재를 하거나 재물이 들어오게 될 재수 있는 꿈이다.'),
                                                                                   ('주방', '재물, 횡재, 생활', '한집,주방,두군데,보다', '집안에 심각한 말썽이나 불화가 일어나 식구들간에 의리가 손상되며 재물이 흩어지고 경영하는 일에 장애가 생겨 성취를 거두기 힘들고 두 집 살림을 차리거나 분가 등 이중살림을 하게 된다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('창고', '재물, 지식, 기반', '관이나,그관속,송장,보다', '재물을 얻게 된다. 또는 어떤 일에 있어 물질적인 성과나 돈을 얻게 된다.'),
                                                                                   ('창고', '재물, 지식, 기반', '들어가다,있다', '경영 및 재물의 관리가 잘 이루어지고 좋은 기회를 만나게 되어 물질적 안정 및 성공을 이루게 된다.'),
                                                                                   ('창고', '재물, 지식, 기반', '자기집,짐,물건,들여오다', '재물이나 사업 자금 등을 끌어오는 것을 의미하는 것으로 이득을 바랄 일이나 좋은 의미에서의 사건을 벌이게 될 것이다.'),
                                                                                   ('창고', '재물, 지식, 기반', '부속건물,바깥채,건축하다', '지위를 얻게 되거나 재물이 늘어나고 사업과 목표로 하는 일이 순조롭게 진행되어 발전하게 된다.'),
                                                                                   ('창고', '재물, 지식, 기반', '부속건물,무너지다,부서지다', '집안살림이 기울어 흩어지고 곤란한 일에 휘말리며 사람이 다치는 사고나 중병을 앓는 등 재물의 손실과 실패 및 좌절을 겪게 된다.'),
                                                                                   ('창고', '재물, 지식, 기반', '안,들여다,보다', '어떤 기관, 회사나 학교에 청원하거나 연구할 일이 생긴다.'),
                                                                                   ('창고', '재물, 지식, 기반', '안,벗섬,가득,들어차다', '부자가 되거나 입신양명한다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
    ('학교', '배움, 경쟁, 성장', '일반', '학교에 관한 꿈은 배움, 경쟁, 성장, 시험 등과 관련된 암시이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
    ('시장', '거래, 재물, 활동', '일반', '시장에 관한 꿈은 거래, 재물, 사람들과의 활발한 교류와 관련된 암시이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('무덤', '조상, 재물, 변화', '길,가다,묘지,높이,솟다,보다', '고급 관리나 거대한 사업가 등과 상대될 일이 생기거나 직장인이라면 승진 또는 성공을 하여 직위가 높아져 권세가 생긴다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '깊은산,헤매다,무덤,발견하다', '위대한 학자를 만나 정신적으로 감화를 받거나 도움을 줄 지도자 또는 협조자를 만나게 된다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '국립묘지,왕릉,찾다,참배하다', '사업상 어려움에 처해 고위층에 있는 권력자의 도움으로 사업이 잘 풀리게 된다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '공동묘지,자기,무덤,돋보이다,호화롭다', '동료들이나 경쟁상대들 중에서 자신의 능력이나 어떤 배경이 가장 강하다는 것을 의미한다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '공동묘지,걷다,거닐다', '어려움이 해결되고 행운이 찾아올 징조이다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '공동묘지,조상,무덤,찾다,못하다', '어려운 시련이 닥치고 그때 자기를 도와줄 어떤 후원자도 없어서 더욱 큰 시련을 겪게 된다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '공동묘지,신원모르다,시체,묻다', '사회사업에 투자하게 된다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '꽃,만발,무덤,있다', '중년 이후에 이르러 크게 성공하고 사회적인 업적을 남기며 큰 기관을 소유하여 명성과 부귀로움을 과시할 것이다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '능,파헤치다,보다', '새로운 직장을 구하거나 전업을 하게 되고 오랜 기간 연구하던 학문적인 성과를 얻게 된다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '누군가,시체,가매장하다', '어떤 위험한 사건이 생겨 그 일을 감추거나 다른 사람들로부터의 위험을 피해 재물을 감춰둘 일이 생기게 된다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '멀쩡하다,갈라지다,보다', '시험에 합격하여 입학을 하거나 원하는 직장에 취직을 하게 된다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '앞,망부석,서있다,보다', '사업상 중개인을 거쳐야 일이 이루어질 것을 예시한다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '옆,상여,정자,있다,보다', '자신의 집 안이나 가까운 사람에게 큰 인물이 태어나서 명예와 영광을 세상에 과시하게 된다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '불,나다,활활,타다', '어렵게 진행되던 사업이 순조로워져 크게 번성한다. 이로 인해 물질적으로도 여유로운 생활을 하게 될 것을 예시한다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '햇빛,비치다,보다', '하고 있는 사업보다 더 큰 사업을 시작하게 되거나 확장을 하고 직장인이라면 승진을 하게 된다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '손,튀어나오다', '채권자의 빚 독촉으로 고통을 받게 된다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '피,흐르다,보다', '어려운 상황에서 협조 기관의 재정적 도움을 받을 일이 생긴다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '파헤치다,금은보화,쏟아지다', '정신적으로 도움을 받거나 물질적인 유산을 상속받게 되고 학문을 하는 사람이라면 연구 실적을 얻어 신분이 상승된다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '금잔디,잘다듬어지다', '어떤 협조 기관이나 능력있는 협조자의 도움으로 지위가 오르고 명예로워진다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '묘지,비석,무너뜨리다', '남편이나 연인을 잃는 두려움이나 그들로부터 해방되고 싶다는 생각을 나타낸다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '산,돌아다니다,명당자리,선정', '세력 기반을 형성하고 집터 등을 마련하게 되고 횡재할 기회가 생긴다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '새로,관이나,묘지,보다', '차츰 근심과 장애가 흩어지고 피해 및 곤란이 해소되어 안정을 얻게 된다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '어떤,무덤,옆,놀다', '자신이 바라는 곳에 취직이 되거나 계획하고 추진 중인 사업을 벌이게 된다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '오래된,무덤,옆,집터,마련', '전통 있는 회사나 역사가 오랜 회사로 직장을 옮기게 되거나 현실에서도 오래된 집으로 이사를 할 일이 생긴다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '자신,직접,눈으로,무덤,파다,관,묻다,보다', '값진 물품 등을 남몰래 챙길 일이 생길 수 있다. 또는 집을 새로 사들이는 일과 관계하게 된다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '조상,무덤,위,큰나무,꽃,만발', '길몽이다. 직장인이라면 사장이 되거나 승진을 하는 등 명예로운 일이 생기고 집 안에 경사스런 일이 생기고 집안이 번창한다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '조상,산소,찾다,성묘하다', '자신의 힘만으로는 벅찬 일이 생겨 협조자나 유력자를 만나 도움을 청하게 되며 그들의 도움으로 일이 이루어진다.'),
                                                                                   ('무덤', '조상, 재물, 변화', '큰무덤,앞,넘어지다,있다,보다', '힘을 비는 협조자나 협조 기관의 운세가 오래가지 못하고 어려운 상황에 놓이게 되니 줄을 잘 서야 한다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('부모', '보호, 권위, 경고', '갓난아기,어머니,품,젖,먹다', '모든 상황들이 젖줄을 대듯 자신에게 유리한 방향으로 척척 맞아떨어져 승승장구하게 될 징조이다.'),
                                                                                   ('부모', '보호, 권위, 경고', '괴롭히다,해치다,죽이다', '부모님에게 좋은 일이 생길 것을 예시해주는 꿈이다. 부모님이 소원하던 일들이 원만하게 이루어질 징조이다.'),
                                                                                   ('부모', '보호, 권위, 경고', '어머니,걱정,표정,안절부절', '꿈 그대로 어머니가 걱정할 만한 일이 생길 징조이다. 자신의 앞날에 뭔가 불길한 기운이 드리우고 있다는 얘기이다.'),
                                                                                   ('부모', '보호, 권위, 경고', '멀다,떨어지다,만나다', '부모님의 건강에 이상이 생길 것을 예시한다. 혹은 자신의 신상에도 불길한 일이 생길 흉몽이다.'),
                                                                                   ('부모', '보호, 권위, 경고', '버스,기차,출발,어머니,뛰어오다,손짓', '현재 하고 있는 일이나 계획하고 있는 일을 당장 그만두라는 강력한 경고로 받아들여야 한다.'),
                                                                                   ('부모', '보호, 권위, 경고', '부녀,모자,남매,근친상간', '자신이 상당히 외롭고 소외감을 느끼고 있다는 의미이다. 따뜻한 사람에게 목말라하고 있지만 정작 가장 가까운 사람들이 알아주지를 않는다.'),
                                                                                   ('부모', '보호, 권위, 경고', '부모,죽다,통곡,슬퍼하다', '유산을 받게 되거나 어려운 상황에 있던 작품이나 사업, 일 등이 성취된다.'),
                                                                                   ('부모', '보호, 권위, 경고', '부모,여행,떠나다,배웅,손흔들다', '꿈속에서 아무리 화목하고 평화로운 분위기였다 하더라도 일단 부모님이 만길을 떠나고 가족들이 배웅을 했다면 불길한 꿈이다.'),
                                                                                   ('부모', '보호, 권위, 경고', '부모,함께,길,걷다', '모든 것이 순조롭고 가정이 화목해짐을 예시한다.'),
                                                                                   ('부모', '보호, 권위, 경고', '아버지,오래된,낡은,양복,입다', '부동산이나 사업 등의 유산이나 집안 재산을 상속받게 될 것을 암시하는 꿈이다.'),
                                                                                   ('부모', '보호, 권위, 경고', '아버지,자전거,뒤,타다', '아버지와 동일시될 수 있는 윗사람 또는 자신에게 도움을 줄 사람 등의 도움으로 어떤 새롭고 좋은 일이 일어날 것을 예시하고 있다.'),
                                                                                   ('부모', '보호, 권위, 경고', '어머니,노발대발,화내다,꾸중', '어머니가 꾸중을 하는 내용이 무엇이든 어머니가 화를 냈다는 그 자체에 주목해야 한다. 자신도 깨닫지 못하는 사이에 큰 오류나 실수를 범하고 있다는 것을 알려주고 있는 것이다.'),
                                                                                   ('부모', '보호, 권위, 경고', '어머니,무섭다,흉악,얼굴,변하다,쫓아오다,목조르다', '내용상으로는 무서운 꿈이지만 해몽은 다르다. 어머니가 지나치게 자신의 모든 일에 간섭하고 있거나 자신에게 너무 큰 기대를 걸고 있어서 부담감에 짓눌려 있다는 것을 보여준다.'),
                                                                                   ('부모', '보호, 권위, 경고', '어머니,방,몸져눕다,병원,입원', '꿈속에서의 어머니는 어떤 사업체나 일거리, 재산을 상징한다고 할 수 있다. 형제 자매들이 재산상 다툴 일이 있거나 같은 사업체나 재산을 나눠 받을 일이 있음을 암시한다.'),
                                                                                   ('부모', '보호, 권위, 경고', '어머니,하사한,웨딩드레스,고운한복,신부,결혼', '불길한 꿈이다. 어머니에게 심각한 우환이 닥칠 징조로서 큰 병에 걸리거나 돌아가실 수도 있다고 경고하는 꿈이다.'),
                                                                                   ('부모', '보호, 권위, 경고', '어머니,젖,빨아먹다', '형제 자매들이 재산상 다툴 일이 있거나 혹은 같은 사업체나 재산을 나눠 받을 일이 있음을 암시한다.'),
                                                                                   ('부모', '보호, 권위, 경고', '싫어하다,직장상사,불리다,얼굴,아버지,이상하다', '평소 권위적인 직장상사와 아버지에 대한 거부감과 반발심이 나타난 것이라고 본다.'),
                                                                                   ('부모', '보호, 권위, 경고', '자다,깨다,어머니,머리맡,서다,얼굴,내려다보다', '어머니의 신상에 좋지 않은 일이 일어날 것을 암시하거나 또는 자식인 자신에게 위험이 닥치고 있다는 것을 예시하는 것이다.'),
                                                                                   ('부모', '보호, 권위, 경고', '자신,어머니,여러명,아이,돌보다', '자신의 능력을 인정받지 못해 좌절감에 빠지게 될 꿈. 구설수에 오르거나 사건에 휘말리게 될 것을 알려주는 경고의 꿈이다.'),
                                                                                   ('부모', '보호, 권위, 경고', '자신,부모,싸우다,몰래,다가가다,죽이다', '이제 바야흐로 자신의 시대가 도래했음을 알려주는 꿈이므로 오히려 좋은 꿈이라고 할 수 있다.'),
                                                                                   ('부모', '보호, 권위, 경고', '자신,어린아이,어머니,칭얼대다', '현재 감당하기 어려운 난감한 상황에 빠져 있을 때 이런 꿈을 꾸게 된다. 회피하지 말고 문제를 해결해 나갈 것.'),
                                                                                   ('부모', '보호, 권위, 경고', '평소,잘알다,사람,어머니,죽이다,목격하다', '앞을 가로막고 있던 장애물들이 사라지고 좋은 기회들이 열리게 된다. 그동안 답답하게 여겼던 상황에서 벗어나 자유롭게 뭔가를 해볼 수 있는 시기가 온 것이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('부부', '관계, 갈등, 변화', '남편,애인,백마,기사,차림,나타나다', '막연히 낭만적인 사랑을 꿈꾸는 미혼 여성이 이런 꿈을 꾸었을 때는 단순히 평소의 소망이 반영된 꿈이다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '남편(아내),만족스럽다,성관계', '꿈과는 반대로 자기 남편(아내)과의 성관계에 만족스럽지 못한 경우에 이런 꿈을 꾸게 된다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '남편(아내),심각한,냉전', '남편(아내)의 건강에 심각한 이상이 발견될 징조이므로 하루라도 빨리 병원을 찾아 진찰을 받아 보는 것이 좋겠다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '남편(아내),함께,호화,유람선,호텔,레스토랑,식사', '부부간의 사이가 많이 벌어져 있다는 것을 나타내는 꿈이다. 결국 관계가 회복되지 못하고 이혼하게 되기 쉽다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '남편(아내),함께,모처럼,나들이,외출', '부부간의 관계가 너무 소원해지거나 이렇게 나기다가는 위태로운 지경에 빠질지도 모른다는 것을 경고하는 꿈이다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '남편(아내),시체,버려지다,발견,놀라다', '남편(아내)에게 뜻하지 않은 행운이 찾아올 꿈이다. 잘 풀리지 않았던 일이 있었다면 한꺼번에 풀리게 되고 걱정거리가 사라진다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '남편(아내),낯선여자(남자),수군거리다,자신,관한,이야기,불쾌', '실제로 남편(아내)에게 다른 여자(남자)가 생겨 자신에 관해서 이러쿵저러쿵 얘기했을 가능성이 높다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '남편(아내),바람,피우다,속,끓이다', '이런 꿈을 꾸고 나면 은근히 남편(아내)에게 신경이 쓰이겠지만 실제로는 그와 반대이다. 오히려 자기 자신이 바람을 피우고 싶은 욕망이 있기 때문에 이런 꿈을 꾸게 되는 것이다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '남편(아내),엄연히,있다,다른사람,새로,결혼', '대단히 불길한 꿈이다. 남편(아내)과 사별하게 될 가능성이 높다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '남편(아내),말걸다,자신,쌀쌀,대꾸,않다', '평소에 부부간에 대화가 부족하거나 자신에게 좀더 따뜻하고 자상하게 신경 써 주지 않는 상대방 때문에 불만을 느끼고 있을 경우 그에 대한 일종의 보복심리로 꿈에서는 이와 같이 나타나는 것이다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '남편(아내),애인,어깨,주무르다,아프다', '성(性)과 관계된 꿈이다. 현재 자신은 성에 대한 욕구가 팽배해 있는데 상대방이 그것을 만족스럽게 채워주지 않기 때문에 꿈속에서는 반대로 이렇듯 강한 자극을 느끼게 되는 것이다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '남편,함껏,끌어안다', '기쁜 일이 생기거나 생각지도 않던 돈, 재물, 이권 등을 얻게 될 것을 예시한다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '남편,머리카락,빠지다,대머리,약국,사오다', '남편과의 잠자리가 만족스럽지 못해 불만이거나 남편의 건강이 약해지는 것 같아 불안해하고 있다는 증거이다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '남편,바람,피우다,아이,낳다,욕설,퍼붓다', '남편의 일이 잘 되어 소득이 생길 꿈. 욕을 퍼붓고 감정을 푼 것은 그 일에 대해서 처음에는 불안감이나 불만스러운 감정이 있었으나 나중에 크게 만족할 일이 있게 될 것임을 암시한다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '남편,자신,밧줄,꽁꽁,묶다,울다', '남편이 자신에게 마음이 식었다거나 관심이 없어졌다고 느껴 서운하거나 불안한 경우에 이런 꿈을 꾼다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '남편,화장실,대변,보다', '직장, 혹은 하는 일, 사업 등에서 실력을 인정받게 된다. 혹은 부지런히 움직임으로써 성공을 보장받을 수 있게 될 것이다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '배우자,함께,부부동반,모임,나가다', '부부 사이에 어떤 좋지 않은 기류가 흐르고 있음을 나타내는 꿈이다. 서로 화합하여 더 이상 나쁜 상황으로 전개되지 않도록 주의해야 한다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '부부,서로,맞절,하다', '부부간에 상처하게 되거나 이혼할 수 있다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '부부,함께,어떤,길,걷다', '재산상의 손실이 있게 될 것을 예시한다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '부부싸움,하다', '치고받으며 요란하게 싸우는 꿈이었다면 부부 사이에 애정이 더 두터워져 행복해질 것이다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '아내,간통,목격하다', '아내는 어떤 일에 대한 상징일 가능성이 많다. 즉, 일이나 직업, 사업체 등의 상징으로 어떤 성질이 다른 일이 결합되거나 인연을 맺을 때 표현되는 것이다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '아내,남편,넥타이,매주다,조여주다', '배우자와의 사별, 이별을 예시하는 흉몽이다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '아내,담밑,아이,낳다', '직장인이라면 승진을 하게 되거나 취직을 기다리는 사람은 소원을 성취하게 된다. 또한 횡재수가 있어 돈이 들어올 것이다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '아내,이별,서럽게,울다', '근심 걱정이 사라지고 전화위복하여 대길할 꿈이다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '아내,얼굴,수염,나다,놀라다,이상하다', '자신이 깨닫지 못하고 있을지라도 무의식 속에서는 아내에게 대단히 주눅이 들어 있는 상태이다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '자기,남편(아내),대변,보다,지켜보다', '남편(아내)에게 재물운이 든다는 것을 암시한다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '자기,남편(아내),있다,또다른,남자(여자),남편(아내),나오다', '반대로 자신의 남편(아내)에게 불륜의 문제가 생겼다는 것을 알려주는 꿈이다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '자신,배우자,다른사람,새로,결혼', '대단히 불길한 꿈이다. 남편(아내)과 사별하게 될 가능성이 높다.'),
                                                                                   ('부부', '관계, 갈등, 변화', '퇴근,남편,술취하다,얼굴,시뻘겋다', '남편의 신상에 위험이 닥칠 것에 대한 경고로 보아야 한다. 불의의 사고를 당하거나 심장마비, 뇌졸중 등의 갑작스러운 질환이 우려된다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
    ('자녀', '미래, 희망, 걱정', '천사,선녀,하늘,날아,올라가다,보다', '인생의 전환기를 맞게 될 것을 암시한 꿈이다. 자기 앞에 지금까지와는 다른 새로운 삶이 펼쳐져 있다는 것을 보여준다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('형제', '경쟁, 협력, 변화', '집안,재산,비용,분담,형제,다툼,의견,분분,불편', '현실 속에서 재산 문제로 형제들과 싸우고 있는 상황이 아닌데 느닷없이 이런 꿈을 꾸었다면 필시 부모님에게 변고가 생길 징조이다.'),
                                                                                   ('형제', '경쟁, 협력, 변화', '형이나,언니,또는,동생,함께,이야기,갑자기,혼자,남다,당황', '지금까지 일이 순조롭게 잘 진행돼 왔다 하더라도 도중에 갑자기 잘못될 가능성이 있다. 동업자나 투자자가 손을 떼는 같은 계열 회사, 자매회사, 거래처 등에 문제가 발생해서 그 여파로 자신에게까지 손해를 입히게 된다.'),
                                                                                   ('형제', '경쟁, 협력, 변화', '형이나,오빠,함께,길,걷다', '현실에서 형이나 오빠와 함께 어떤 일을 진행시킬 것을 예시하는 꿈. 또는 오빠나 형이 직장상사의 동일시 인물일 경우에는 그와 더불어 어떤 일을 진행시키게 될 것이다.'),
                                                                                   ('형제', '경쟁, 협력, 변화', '형제(자매),결혼하다', '꿈속에서 결혼을 한 그 형제(자매)에게 뭔가 불길한 일이 닥칠 것을 암시하는 꿈이다.'),
                                                                                   ('형제', '경쟁, 협력, 변화', '형제(자매),사고,죽다', '꿈속에서 형제의 불의의 사고로 죽었다는 것은 자기 주변의 경쟁자를 물리치고 싶다거나 그 경쟁자가 없어졌으면 좋겠다는 바램이 나타난 것으로 볼 수 있다.'),
                                                                                   ('형제', '경쟁, 협력, 변화', '형제(자매),모이다,담소,즐겁다,시간', '부모님에게 변고가 생기거나 형제 중에 우환을 겪을 사람이 생길 것을 암시한다.'),
                                                                                   ('형제', '경쟁, 협력, 변화', '형제(자매),한곳,모이다,집안,물건,서로,나누다', '부모님에게 좋지 않은 일이 일어날 수도 있고 집안 전체에 나쁜 일이 생길 수도 있다.'),
                                                                                   ('형제', '경쟁, 협력, 변화', '형제자매,한방,둘러앉다', '집안에 우환이 생기거나 자신의 신변에 좋지 않은 일이 생기게 될 것을 예시한다.'),
                                                                                   ('형제', '경쟁, 협력, 변화', '형제끼리,주먹질,엎치락뒤치락,몸싸움', '꿈속에서의 싸움, 특히 몸싸움은 문제의 해결, 해소라는 의미가 있다. 형제(자매)와 치고 박고 싸웠다는 것은 집안에 얽혀 있던 문제들이 해결될 조짐이 보인다는 뜻으로 해석할 수 있다.'),
                                                                                   ('형제', '경쟁, 협력, 변화', '형이나,자매,함께,장작,패다', '유산 상속이나 재산상의 문제로 형제자매들 사이에서 불화가 생길 것을 예시한다.'),
                                                                                   ('형제', '경쟁, 협력, 변화', '형제들,모이다,함께,나들이,여행,가다', '가정 내에 불화가 생기거나 어려운 일을 당할 조짐이다. 꿈속에서 들뜨고 즐거운 기분일수록 더욱 좋지 않다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('조상', '유산, 경고, 도움', '돌아가신,부모님,조상,눈물,흘리다', '자신, 혹은 형제들에게 위험이 닥쳐오거나 가세가 기울게 될 것을 예시한다. 사업이 크게 실패하거나 집안에 흉사 등이 있을 수 있다.'),
                                                                                   ('조상', '유산, 경고, 도움', '돌아가신,조상,자신,쓰다듬다', '흉몽이다. 흉사가 생기거나 질병에 걸리게 되며 가족 중 누군가를 쓰다듬는 꿈이었다면 가족 중 누군가가 중병에 걸리거나 사망하고 집 안에 흉사가 생길 것이다.'),
                                                                                   ('조상', '유산, 경고, 도움', '돌아가신,할머니,할아버지,살아,나들이,데리고,가려하다', '불의의 사고나 질병으로 죽게 되거나 그에 못지 않은 우환이 닥친다는 경고이다.'),
                                                                                   ('조상', '유산, 경고, 도움', '돌아가신,할아버지,농가구,챙기다,밭,갈다', '아버지나 혹은 집안의 가장이 직장을 옮기거나 이사를 하게 된다. 아버지나 집안의 가장이 사업가인 경우 논과 밭이 기름지게 갈아졌다면 사업이 순조롭게 이루어지게 될 것이다.'),
                                                                                   ('조상', '유산, 경고, 도움', '돌아가신,할아버지,밭,일,하다', '자신의 생활을 돌아볼 필요가 있다. 이러한 꿈은 자신의 현재의 생활이 방탕하거나 절제가 필요함을 경고하는 꿈이다.'),
                                                                                   ('조상', '유산, 경고, 도움', '돌아가신,할아버지,손자,어루만지다', '돌아가신 할아버지가 생전에 예뻐하던 손자를 어루만지는 꿈은 현실에서 그 손자가 병들게 된다.'),
                                                                                   ('조상', '유산, 경고, 도움', '돌아가신,할아버지,어디서,암소,끌다,안마당,외양간,매다', '머지 않아 그 집 며느리나 가정부, 아내 등을 맞이하게 될 것이다. 혹은 외부에서 재물을 들여올 수도 있다.'),
                                                                                   ('조상', '유산, 경고, 도움', '돌아가신,할아버지,할머니,자신,믿음,하려하다', '자신이 꼭 알아야 할 일, 미리 알고 조치하거나 조심해야 할 어떤 일이 있다는 의미이다.'),
                                                                                   ('조상', '유산, 경고, 도움', '돌아가신,할아버지,할머니,즐겁다,데리고,어디론가,가려하다', '구설수에 휘말리게 되거나 뜻밖의 사고를 당할 수 있다. 혹은 죽음이나 어떤 우환이 일어날 수 있으니 조심해야 한다.'),
                                                                                   ('조상', '유산, 경고, 도움', '돌아가신,할아버지,사신앞,절,하다', '조상 대대의 유산이나 문중 재산을 상속받을 일이 생길 것이다. 또는 계획하는 일이나 사업이 크게 성공하여 막대한 부를 누릴 수 있게 될 것이다.'),
                                                                                   ('조상', '유산, 경고, 도움', '제사,지내다,조상,와서,제물,먹다,보다', '일을 부탁 받은 사람이 일을 수월하게 성사시켜 줄 것을 예시한다.'),
                                                                                   ('조상', '유산, 경고, 도움', '조상들,쓰던,밥그릇,얻다', '유업을 계승하거나 전통적인 일에 종사하게 됨을 예시한다.'),
                                                                                   ('조상', '유산, 경고, 도움', '조상,큰절,하다', '집안 또는 기관에서 어떤 상속을 받거나 그 기관에 청탁할 일이 생긴다.'),
                                                                                   ('조상', '유산, 경고, 도움', '조상,숟가락,받다', '재산을 상속받을 일이 생긴다.'),
                                                                                   ('조상', '유산, 경고, 도움', '조상,집,들어오다', '그 조상이 높은 관직에 있었거나 명망이 높거나 집안을 크게 일으킨 인물이었다면 현실에서도 집이 크게 일어나거나 관직에 나아가게 될 것이다.'),
                                                                                   ('조상', '유산, 경고, 도움', '조상,집,나가다', '살림이 궁색해진다.'),
                                                                                   ('조상', '유산, 경고, 도움', '죽은,조상,평상시,나타나다,불의,사고,또다시,죽다', '과거에 한번 성취되어 명성을 얻었던 일이 다시 성취되어 기쁨을 누리게 된다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('선생님', '권위, 배움, 경고', '과거,은사,존경하다,보다', '자신의 일이나 사업에 협조적인 사람을 만나거나 자신에게 호의를 보일 사람을 만난다.'),
                                                                                   ('선생님', '권위, 배움, 경고', '교실,가다,자신,책상,의자,찾다,못하다,당황', '입시나 취업 승진시험 등에서 떨어진다. 혹은 현실에서 자신의 자리나 위치에 대한 불안감이 그렇게 나타난 것일 수도 있다.'),
                                                                                   ('선생님', '권위, 배움, 경고', '교실,강당,선생님,설명,듣다', '사업이나 추진하는 일이 난관에 부딪혀 다시 검토해야 할 일이 생긴다.'),
                                                                                   ('선생님', '권위, 배움, 경고', '선생님,들판,걸어오다,보다', '어떤 일이나 사업이 자신의 혼자 힘으로는 풀리지 않으며 어떤 협조자나 협조 기관의 도움을 받아야만 풀린다.'),
                                                                                   ('선생님', '권위, 배움, 경고', '자신,선생님,되다,학생,가르치다', '많은 사람들을 향해 자신의 사상이나 이념, 이론 등을 널리 알리게 될 일이 있을 것이다.'),
                                                                                   ('선생님', '권위, 배움, 경고', '존경하지않다,선생님,보다', '학생이 이런 꿈을 꾸는 것은 평소 선생님에 대한 반발심이나 두려움이 나타난 것이고 일반인이 이런 꿈을 꾸면 윗사람이나 직장상사에게 책망을 듣게 되거나 불쾌한 일이 생긴다.'),
                                                                                   ('선생님', '권위, 배움, 경고', '좋아하다,선생님,들판,혼자,걸어오다', '계획하던 일의 성과가 바로 나타나지 않고 오랜 시간이 흐른 후에 성공을 거두게 되는 꿈이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('친구', '관계, 경쟁, 우정', '사이,나빠지다,연락,않다,친구,애인,악수', '꿈 그대로 멀어진 친구와 화해하고 싶다는 심리가 반영된 꿈이다.'),
                                                                                   ('친구', '관계, 경쟁, 우정', '사이,좋지않다,친구,맞다', '현실에서는 사이가 좋지 않겠지만 꿈에서 맞는 꿈은 오히려 반대로 해석이 된다. 정신적인 불안과 앓고 있던 병이 낫게 되거나 사이가 좋지 않은 그 친구와 어떤 계기로 우정을 쌓게 될 것을 예시한다.'),
                                                                                   ('친구', '관계, 경쟁, 우정', '오래,알다,친구,나타나다,어려움,호소,동정,구하다', '가족들 중 누군가가 질병에 걸릴 수 있으므로 조심해야 한다. 혹은 연인과의 사이에 뜻밖의 일이 생겨 당황하게 되거나 공과 사를 분명히 하지 못해 낭패를 볼 수 있다.'),
                                                                                   ('친구', '관계, 경쟁, 우정', '자신,친구,부모님,인사하다', '상관이나 윗사람에게 뭔가 청원할 일이 생기며 청원이 받아들여질 것이다.'),
                                                                                   ('친구', '관계, 경쟁, 우정', '친구,남루한,옷,입다,보다', '현실에서 그 친구의 학식이나 능력이 보잘 것 없음을 나타낸다. 혹은 그 친구가 실직 상태에 고독한 상태를 의미하기도 한다.'),
                                                                                   ('친구', '관계, 경쟁, 우정', '친구,충고,조언,듣다', '자신이 모르고 있는 동안 상대나 혹은 조직 속에 배신자가 흉계를 꾸미기 쉽다. 누군가의 유혹이나 어떤 속임수를 조심해야 한다.'),
                                                                                   ('친구', '관계, 경쟁, 우정', '친구,낯선곳,다정하게,이야기,나누다', '친구와 사이가 나빠지거나 싸우게 될 것을 예시한다.'),
                                                                                   ('친구', '관계, 경쟁, 우정', '친한,친구,말싸움,하다', '직장인은 업무로 인해 곤란한 입장에 빠지게 되거나 공연한 구설수에 휘말려 정신적인 고통을 당하게 될 것이다.'),
                                                                                   ('친구', '관계, 경쟁, 우정', '평소,미워하다,친구,만나다', '질병에 걸릴 것을 암시하므로 주의해야 한다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('물', '생명, 재물, 감정', '그릇,담기다,실수,잃다', '재물의 손실을 가져올 일이 생기고 소원이 좌절되며 그동안 추진하던 계약이나 회담이 실패하게 된다.'),
                                                                                   ('물', '생명, 재물, 감정', '길가,분수,높이,솟아치다,보다', '사업이 성황을 이루거나 뛰어난 업적을 과시하게 되며 광고할 일이 계속 생기게 된다.'),
                                                                                   ('물', '생명, 재물, 감정', '누군가,자신,떠밀다,빠뜨리다', '자신에게 악의를 품고 있는 사람에게 이용 당하거나 속아넘어가 큰 피해를 입게 되거나 자신의 허점이 드러남으로써 공격을 당하게 된다.'),
                                                                                   ('물', '생명, 재물, 감정', '동물,물속,들어가다,자취,감추다', '어떤 일이 끝이 보이지 않거나 자신과 관계 있는 인물이 실종될 것을 예시한다.'),
                                                                                   ('물', '생명, 재물, 감정', '두줄기,집,흘러,들어와,하나,물줄기,이루다', '자신과 관계하지 않았던 두 군데의 일에서 재물을 얻게 된다.'),
                                                                                   ('물', '생명, 재물, 감정', '맑은물,빨래감,깨끗,세탁하다', '사업이나 취직이 순조롭게 이루어진다.'),
                                                                                   ('물', '생명, 재물, 감정', '뜨겁다,마시다', '그동안 정신적 물질적으로 많은 어려움이 있어서 가장 신경이 쓰이던 사업이 다른 사람의 도움으로 성사된다.'),
                                                                                   ('물', '생명, 재물, 감정', '맑다,보다', '장래의 전망이 밝아 하는 일이 잘 되고 집안이 화평하며 건강도 양호하다는 신호이다.'),
                                                                                   ('물', '생명, 재물, 감정', '묵다,타다,찾다,못하다', '급하게 필요한 돈을 구하지 못해 낭패를 보게 될 암시이다.'),
                                                                                   ('물', '생명, 재물, 감정', '위,걷다', '매사가 순조롭게 발전하고 소원이 성취될 길몽이다.'),
                                                                                   ('물', '생명, 재물, 감정', '물길,두갈래,갈라지다', '자기의 신앙이나 사업이 기로에 서 있음을 의미하는 것이다.'),
                                                                                   ('물', '생명, 재물, 감정', '물바다,들판,가운데,서다', '권력자 세도가 힘있는 사람 고귀한 신분의 사람과 인연을 맺게 되며 이들로부터 도움을 받아 소원 추진하는 일 사업 등이 크게 이루어진다.'),
                                                                                   ('물', '생명, 재물, 감정', '빠지다,죽다,보다', '큰 이득을 얻고 행운이 찾아올 암시이다.'),
                                                                                   ('물', '생명, 재물, 감정', '빠지다,구조되다', '하고자 하는 일에서 성공을 거두고 위험을 비껴나가게 될 행운의 꿈이다.'),
                                                                                   ('물', '생명, 재물, 감정', '긷다,물통,없다,바가지,굴러나오다', '동업자에게 사기를 당하거나 사업에 아무 이익도 내지 못해 중도 포기하게 될 것을 예시한다.'),
                                                                                   ('물', '생명, 재물, 감정', '마시다,부엌,가다,맑은샘,변하다,갈증,해소되다', '커다란 행운이 찾아올 것이다. 그간 어려움을 겪던 일들이 일순간에 해결의 실마리를 찾게 되며 사업은 나날이 번창하게 된다.'),
                                                                                   ('물', '생명, 재물, 감정', '붓다,그릇,넘쳐흐르다', '돈 쓸 일이 생기게 되고 물이 끊이지 않고 넘쳤다면 계속해서 그만큼의 지출이 따르게 된다.'),
                                                                                   ('물', '생명, 재물, 감정', '퍼내다', '외부로부터 협조를 얻게 된다. 또는 유용한 정보를 얻게 된다.'),
                                                                                   ('물', '생명, 재물, 감정', '그릇,빨래감,담다,보다', '새로운 직업에 종사하게 되고 재물이나 명예가 생겨서 신분이 새로워지거나 하는 일마다 성공을 거두어 호평을 받게 된다.'),
                                                                                   ('물', '생명, 재물, 감정', '개울물,갑자기,밀리다,바닥,보이다', '사업 자금이 고갈되어 사업이 어려운 상황에 놓이게 된다.'),
                                                                                   ('물', '생명, 재물, 감정', '유유히,흐르다,보다', '매사에 막힘 없이 발전하게 될 것을 암시한다.'),
                                                                                   ('물', '생명, 재물, 감정', '밑빠진,독,계속,길어다,붓다', '아무리 열심히 일을 해도 어려운 상황이 지속되고 돈 쓸 일이 생긴다.'),
                                                                                   ('물', '생명, 재물, 감정', '방,가득,차다', '일이 잘 풀리고 그로 인해 재물을 쌓아두게 되며 정신적인 면에 관련된 일에 종사하게 된다.'),
                                                                                   ('물', '생명, 재물, 감정', '부엌,가득,차다,넘쳐흐르다', '집 안에 경사가 생기고 큰 재물이 생긴다.'),
                                                                                   ('물', '생명, 재물, 감정', '비어있다,집,물탱크,가득차다,보다', '예상하지 못했던 막대한 돈이 생긴다.'),
                                                                                   ('물', '생명, 재물, 감정', '사방,온통,물바다,변하다', '길몽이다. 학문이나 예술 작품 활동 업적 등을 통해 명예와 부를 얻게 되거나 세상사람들을 감동시키게 되며 그로 인해 명성을 쌓게 될 것을 예시한다.'),
                                                                                   ('물', '생명, 재물, 감정', '송장,썩다,냇물,흐르다', '사업이 크게 번성하여 많은 돈을 벌게 되고 여러 사람들에게 정신적인 영향을 주어 명예를 얻게 된다.'),
                                                                                   ('물', '생명, 재물, 감정', '선반,구멍,물,가득,담기다,새다,살피다', '여러 개의 사업체를 운영하면서 자금 사정이 어렵게 되어 소비를 억제할 일이 생기게 된다.'),
                                                                                   ('물', '생명, 재물, 감정', '자기집,스며나와,고이다,보다', '집 안이나 자손 중에 근심이 생길 것을 예시한다.'),
                                                                                   ('물', '생명, 재물, 감정', '자기집,빈독,사람들,아무이유없다,물,퍼다,부어주다', '갑작스럽게 여러 사람들로부터 물질적 후원을 받거나 돈을 받을 일이 생겨 재산을 쌓게 된다.'),
                                                                                   ('물', '생명, 재물, 감정', '자신,파놓다,웅덩이,펑펑,솟아나다', '사회 사업이나 공공기관 또는 자신이 다니고 있는 회사를 통해 돈을 벌게 된다.'),
                                                                                   ('물', '생명, 재물, 감정', '집아니다,다른곳,아무이유없다,물,한동이,한통,길어오다', '용기가 필요한 일이 생기게 되고 그 일을 처리하고 난 후에는 그에 상응하는 재물이 생겨 어려움이 사라진다.'),
                                                                                   ('물', '생명, 재물, 감정', '탁하다,보다', '좋지 않은 사고 방식 문란한 생활 심신의 건디선 악화를 상징하는 흉몽이다.'),
                                                                                   ('물', '생명, 재물, 감정', '하늘,산,들,몽땅,물,덮이다,보다', '큰 세력을 잡아서 자신의 세력으로 만들게 되거나 세상을 감동시키고 구할 업적을 남기게 된다.'),
                                                                                   ('물', '생명, 재물, 감정', '흐리다,이끼,끼다,빨래하다', '사업이 어려운 지경에 이르게 되고 소원이나 추진하던 일이 잘 이루어지지 않는다.'),
                                                                                   ('물', '생명, 재물, 감정', '흘러가다,흙더미,막히다,고이다', '흘러가던 물이 막혀 웅덩이가 되거나 자수지가 되는 꿈은 재물을 모으게 될 것을 암시하는 꿈이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('땅', '기반, 재물, 안정', '돌투성이,황무지,개간하다', '새로운 것에 대한 도전의 욕구가 강렬한 상태이다. 자기 뜻대로 일을 밀고 나가기 위해서 주위 사람들을 강력하게 설득하고 있음을 나타내고 있다.'),
                                                                                   ('땅', '기반, 재물, 안정', '기름,솟아,흐르다', '삶의 진리와 사상을 전파할 일에 종사하게 된다.'),
                                                                                   ('땅', '기반, 재물, 안정', '팔다,돈,받다', '자기가 가지고 있던 능력이나 자산이 갑작스럽게 좋은 평가를 받게 되어 두각을 나타내게 된다. 실업자라면 취직을 하게 되고 직장인이라면 승진하게 된다.'),
                                                                                   ('땅', '기반, 재물, 안정', '갈라지다', '직장이나 가정에 우환과 걱정거리가 생길 암시이다. 무조건 피하려고 하기보다는 고난에 대한 준비를 미리 해두는 쪽이 현명하다.'),
                                                                                   ('땅', '기반, 재물, 안정', '꺼지다', '사회적으로 중대한 변란이나 변고가 일어날 것을 예시하는 꿈이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('산', '목표, 도전, 성공', '높다,걸어,내려오다', '사업이나 추진 중인 일이 순조롭게 잘 진행될 것을 예시한다. 그러나 높은 지위에 있거나 신분이 고귀한 사람이 이런 꿈을 꾸게 되면 신분이 몰락하게 되거나 좌천 강등될 것을 예시한다.'),
                                                                                   ('산', '목표, 도전, 성공', '눈덮이다,오르다', '소원을 성취하기 위해서는 난관을 극복해야만 한다는 암시이다. 그 고비를 넘고 나면 성공이 눈앞에 보인다.'),
                                                                                   ('산', '목표, 도전, 성공', '위,크게,소리,지르다', '자신이 하고 있는 일이 크게 성공하여 이름을 떨치게 되거나 사람들의 입에 오르내리게 될 것이다.'),
                                                                                   ('산', '목표, 도전, 성공', '산꼭대기,올랐다,더,하늘,올라가다', '이 꿈은 좋지 않다. 산꼭대기까지 올라간 것은 총이나 발이 땅에서 떨어져 더 올라갔다는 것은 은퇴를 의미한다.'),
                                                                                   ('산', '목표, 도전, 성공', '산꼭대기,오르다', '정상에 올라 기쁜 마음으로 야호 하고 함성을 질렀다면 원하던 바를 이루고 대성공을 이룰 길몽이다.'),
                                                                                   ('산', '목표, 도전, 성공', '불,나다,보다', '불이 나는 꿈은 길몽이지만 만약 불꽃 없이 연기만 나는 꿈이었다면 하는 일이나 사업이 답답하고 잘 풀리지 않게 된다.'),
                                                                                   ('산', '목표, 도전, 성공', '안개,아지랑이,끼다', '추진 중인 일이나 사업 등이 잘 이루어지지 않아 답답한 상황이 전개될 것이다.'),
                                                                                   ('산', '목표, 도전, 성공', '낯선사람,만나다,이야기,나누다', '협조자나 후원자를 만나 어려움을 극복하고 성공하게 된다.'),
                                                                                   ('산', '목표, 도전, 성공', '오르다,떨어지다', '자기의 직위나 직급 신분 등이 떨어지거나 몰락하게 될 것이다. 또는 계획하는 일이나 소원이 좌절될 것을 암시하는 것이다.'),
                                                                                   ('산', '목표, 도전, 성공', '통째로,떡조각,먹어버리다', '정당이나 사회 단체 국가 조직 기업 등을 거느리거나 지배하게 될 사업가나 정치가 권력자들이 꾸는 꿈이다.'),
                                                                                   ('산', '목표, 도전, 성공', '무너지다,내리다', '회사가 도산하게 될 암시이다. 직장을 잃고 재물의 손실을 입게 될 징조이다.'),
                                                                                   ('산', '목표, 도전, 성공', '소나,말,끌고,오르다', '자식을 얻게 될 암시이다.'),
                                                                                   ('산', '목표, 도전, 성공', '에베레스트,백두산,어마어마,크다,높다,바라보다', '소원을 성취할 길몽이다. 그러나 그 크고 높은 산을 실제로 오르려고 등반을 막 시작하는 꿈이었다면 소원을 성취하기까지 많은 시간과 노력이 필요하다는 암시이다.'),
                                                                                   ('산', '목표, 도전, 성공', '크고높다,정상,흰눈,덮이다,빛나다,보다', '높은 사람 눈에 띄어 인정을 받고 신분 상승의 기회가 주어질 꿈이다. 많은 사람 앞에서 칭찬을 받고 명예를 얻게 된다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('돌', '장애, 견고함, 장수', '돌덩이,자기집,울타리,쌓다', '많은 사람들의 도움으로 사업 기반을 공고히 다지거나 자기의 직위 신분 등을 더 공고히 하게 될 것이다.'),
                                                                                   ('돌', '장애, 견고함, 장수', '안거나,짊어지다,자기집,들어오다', '재물이나 이권 권리 명예 보물 등을 얻게 된다.'),
                                                                                   ('돌', '장애, 견고함, 장수', '쌓아놓다,돌무더기,허물어지다', '계획 중인 일이나 추진하고 있는 일이 중도에 실패하거나 포기하게 될 것을 예시한다.'),
                                                                                   ('돌', '장애, 견고함, 장수', '여러곳,흩어지다,줍다,그릇,담다', '여러 곳에 깔아 놓은 빚이나 농산물 돈 등을 거두게 될 것을 암시하는 것이다.'),
                                                                                   ('돌', '장애, 견고함, 장수', '자기,들수있다,만하다,작은,돌덩이,점점,커지다,큰바위,되다', '작은 사업체나 일거리였는데 점점 확장되거나 커져 큰 사업체를 일구게 될 것이다. 혹은 미미한 힘이었던 것이 점차 거대한 권력으로 자라나게 될 것이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('강', '흐름, 재물, 변화', '손발,씻다', '취직을 하려는 사람은 취직이 되고 승진을 바라는 사람은 승진을 하고 어떤 계약을 하려는 사람은 계약이 성사될 것이다.'),
                                                                                   ('강', '흐름, 재물, 변화', '손발,씻다,기름,더러워,씻기어렵다', '어떤 일을 열심히 하지만 성과를 얻기 어렵다. 또한 재물이 좀처럼 쌓이지 않고 적성에 맞지 않아 괴로워하면서도 쉽게 그 직장을 벗어나지 못해 당분간 어려움이 계속될 것이다.'),
                                                                                   ('강', '흐름, 재물, 변화', '물살,사납게,출렁거리다,보다', '주변에 시끄럽고 골치 아픈 일이 일어날 암시이다. 가까운 사람과 싸움이 일어나거나 의를 상하게 되고 재판이나 소송에 연루되는 일이 생길 수도 있으므로 주의해야 한다.'),
                                                                                   ('강', '흐름, 재물, 변화', '마르도록,마셔버리다', '크게 횡재하여 큰 부자가 될 수 있는 꿈이다. 또는 막강한 권력자가 되기도 하고 위대한 학자나 사상가가 될 수도 있다.'),
                                                                                   ('강', '흐름, 재물, 변화', '맑게,보이다', '사업이나 어떤 일을 하는 데 있어 그 기반이 튼튼하고 안정되어 전망이 밝다는 것을 의미한다.'),
                                                                                   ('강', '흐름, 재물, 변화', '바다,위,평지같이,걷다', '주위의 모든 여건이 자신에게 유리하게 전개되어 추진하던 일이나 사업 등이 번성하고 원하던 직장에 취직하고 소원이 이루어진다.'),
                                                                                   ('강', '흐름, 재물, 변화', '강가,개울가,빛나다,수석,줍다', '태몽으로 앞으로 태어날 아이가 높은 관직에 올라 크게 성공하게 될 징조.'),
                                                                                   ('강', '흐름, 재물, 변화', '거꾸로,흐르다', '자기의 주장에 대해 주변 사람들로부터 반격이나 공격을 받게 된다.'),
                                                                                   ('강', '흐름, 재물, 변화', '불,붙다', '정신적 물질적인 면에서 어떤 기관과 협력하여 성공을 이루게 될 징조.'),
                                                                                   ('강', '흐름, 재물, 변화', '살얼음,건너다,무사히', '실직이나 시험에서의 불합격 등을 두려워했으나 시험에 합격하거나 승진 영전 등을 하게 된다.'),
                                                                                   ('강', '흐름, 재물, 변화', '얕다,알다,들어가다,깊다,빠지다', '쉽게 생각하고 시작했으나 뜻하지 않은 난관이 닥쳐 어려움을 겪게 될 꿈이다.'),
                                                                                   ('강', '흐름, 재물, 변화', '예쁜,조약돌,강변,줍다', '직장에서 승진하여 관리자가 되거나 학문적인 성과를 얻어 명성을 얻게 된다.'),
                                                                                   ('강', '흐름, 재물, 변화', '자신,빠지다,죽다', '운세가 호전되어 일이 막힘 없이 잘 풀리게 되며 경사스러운 일이 겹칠 징조이다.'),
                                                                                   ('강', '흐름, 재물, 변화', '차,빠지다', '어떤 일의 결과가 다른 곳에 흡수되거나 억압을 받게 된다.'),
                                                                                   ('강', '흐름, 재물, 변화', '크다,물,밀리다,쩍쩍,갈라지다,강바닥,드러나다', '생활이 곤궁해지고 하는 일이 어렵게 될 조짐이다.'),
                                                                                   ('강', '흐름, 재물, 변화', '흐르다,거슬러,올라가다,인간힘,쓰다', '대단히 어려운 상황에 처해 있음을 나타내는 꿈이다.'),
                                                                                   ('강', '흐름, 재물, 변화', '호수,강물,꽁꽁,얼어,붙다', '사업 자금이나 일에 필요한 자금이 동결되거나 정체될 것을 의미한다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('바다', '무의식, 변화, 광대함', '조난,구조,기다리다', '어떤 일이나 사업에 있어 중대한 위기에 직면하게 되며 다른 사람이나 기관 등에 의지해 위험을 극복하려 하게 된다.'),
                                                                                   ('바다', '무의식, 변화, 광대함', '한가운데,우뚝,솟다,높은산,들어가다', '자신의 죽음을 미리 알리는 것이거나 갑작스러운 일로 인해 외국에 갈 일이 생긴다.'),
                                                                                   ('바다', '무의식, 변화, 광대함', '밀려들다,홍수,나다,자기집,잠기다', '뜻밖의 재물이 생기고 사업이 크게 융성하여 큰 재산을 쌓게 된다.'),
                                                                                   ('바다', '무의식, 변화, 광대함', '바닷물,밀려오다,한가롭게,바라보다', '새로운 사조나 유행이 밀려와 자신에게 영향을 미치고 사업가는 사업이 융성해진다.'),
                                                                                   ('바다', '무의식, 변화, 광대함', '바닷물,점점,불어나다,보다', '사업 추진 중인 일 등이 크게 발전하며 대길한 꿈이다.'),
                                                                                   ('바다', '무의식, 변화, 광대함', '바닷물,줄어들다,밀라,바다닥,드러나다,보이다', '사업이 위축되고 하는 일이 점차 그 운이 쇠하여 잘 풀리지 않으며 자금이나 경제적으로 사정이 안 좋아진다.'),
                                                                                   ('바다', '무의식, 변화, 광대함', '해변,일광욕,피부,태우다', '명예와 신분이 높아지고 새로운 직장과 거주지에 변동이 생긴다.'),
                                                                                   ('바다', '무의식, 변화, 광대함', '어둠침침,가운데,감푸다,파도,치다,바라보다', '상황이 좋지 않다는 것을 경고하는 꿈이다. 충동적으로 행동했다가는 큰 피해를 입게 된다는 의미이기도 하다.'),
                                                                                   ('바다', '무의식, 변화, 광대함', '잔잔,햇빛,받아,반짝이다', '운이 트이고 상승세를 타고 있음을 알려주는 길몽이다.'),
                                                                                   ('바다', '무의식, 변화, 광대함', '잔잔,바라보다', '앞길이 순탄하게 열려 있다는 암시이다.'),
                                                                                   ('바다', '무의식, 변화, 광대함', '집앞,바닷물,보이다,집,바다,가까워지다', '사업 계획을 구상하거나 유학이나 외국 출장 이민갈 일 등이 생긴다.'),
                                                                                   ('바다', '무의식, 변화, 광대함', '자신,물고기,되다,헤엄치다', '연구 탐험 추리 출세 등을 하게 된다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('불', '열정, 성공, 변화', '건물안,폭탄,터지다,폭음,불길,휩쓰이다,보다', '지금까지의 어떤 고민거리나 정신적인 고통이 해소되고 사업이나 추진하는 일이 크게 성공하여 많은 재물을 쌓게 된다.'),
                                                                                   ('불', '열정, 성공, 변화', '그릇,물이나,오줌,강물,호수,불,붙다', '자신이 근무하고 있는 기관이나 회사 등에서 정신적으로 도움을 받게 된다. 사업을 하는 사람이라면 사업이 크게 이루어져서 많은 돈을 벌게 되고 지위도 상승된다.'),
                                                                                   ('불', '열정, 성공, 변화', '높은산,일대,불타다,보다', '국가적으로 또는 사회적으로 경사가 생기거나 이와 반대로 큰 환난이나 전쟁이 나기도 한다.'),
                                                                                   ('불', '열정, 성공, 변화', '누군가,밭,불,자기집,옮겨,활활,타다', '꿈속의 그 사람으로 상징되는 사람 혹은 그 상대방의 권리나 이권 등이 이전되거나 재산이나 유산을 받게 되어 부자가 된다.'),
                                                                                   ('불', '열정, 성공, 변화', '대나무밭,얻다,숯,한덩이,화롯불,피우다,쬐다', '어떤 기관이나 단체 사업체 등의 작은 도움을 실마리로 큰 이익이나 혜택을 보게 된다.'),
                                                                                   ('불', '열정, 성공, 변화', '바람,불다,불길,거세지다', '여러 가지 상황이 유리하게 돌아가 사업이 불처럼 일어나게 된다.'),
                                                                                   ('불', '열정, 성공, 변화', '방안,촛불,환하게,켜지다,보다', '사업이나 추진하던 일 소원 등이 만족스럽게 이루어지거나 지금까지 자신을 괴롭혀 왔던 근심이나 걱정거리 고민 등이 해소된다.'),
                                                                                   ('불', '열정, 성공, 변화', '불길,헤치고,사람이나,동물,구해내다', '속한 곳에서 능력을 인정받게 되고 주위 사람들에게 신임을 한 몸에 받으며 협력자를 만나 고비를 넘기게 된다.'),
                                                                                   ('불', '열정, 성공, 변화', '불,끄다', '심신이 쇠약해지거나 갑작스런 재난이나 사고 등으로 어려움을 겪게 될 것을 암시한다.'),
                                                                                   ('불', '열정, 성공, 변화', '불,피우다', '사업이 확 일어나고 재산이 늘어날 암시이다.'),
                                                                                   ('불', '열정, 성공, 변화', '자신의집,마당,흙속,갑자기,한가닥,불길,솟아오르다', '집 안에 좋은 일이 생기거나 사업상으로 한번쯤 신문에 광고할 일이 생긴다.'),
                                                                                   ('불', '열정, 성공, 변화', '자신의집,불,나다,활활,타다', '추진하던 일이나 사업 등이 크게 융성하여 큰 돈을 벌게 된다.'),
                                                                                   ('불', '열정, 성공, 변화', '자신,불,잡아타고,가다', '높은 관직에 오르거나 지위 신분 명예 등이 크게 오르게 된다.'),
                                                                                   ('불', '열정, 성공, 변화', '자신,아는,어떤사람,온몸,불,붙어,타다,보다', '사업이나 추진 중인 일이 번성하여 크게 돈을 벌게 되거나 자신이 하는 일이 세상에 알려지면서 유명세와 더불어 큰 돈을 벌게 된다.'),
                                                                                   ('불', '열정, 성공, 변화', '전기공사,잘못,합선,폭음,공중,큰불,나다', '하고 있는 일이나 계획하던 일이 사회적으로 크게 성공하게 되고 세상을 감동시킬만한 일을 하게 된다.'),
                                                                                   ('불', '열정, 성공, 변화', '지붕,수리하다,화재,나다,건잡다,수없이,끄지못하다', '자신이 대표로 되거나 고위간부층에 있는 사업이 크게 융성하거나 횡재할 꿈이다. 또한 지금 당장은 아니더라도 승진이나 취직 부동산 매입 등의 좋은 일이 반드시 일어날 것을 예시한다.'),
                                                                                   ('불', '열정, 성공, 변화', '집,불길,보지못하다,검은,연기,피어,오르다,보다', '집 안에 불화가 생기게 된다. 혹은 자신이 근무하고 있는 직장에 불길한 일이 생긴다. 직장인들은 승진을 하게 되고 일반인들도 지위가 상승하게 된다.'),
                                                                                   ('불', '열정, 성공, 변화', '차,불길,휩싸이다', '심각한 위험 상황이 다가오고 있음을 암시한다. 또는 감정이 폭발 직전의 상태에 있음을 나타내는 꿈이다.'),
                                                                                   ('불', '열정, 성공, 변화', '타오르다,불길,끄지못하다,발,동동,구르다,두려워하다,불안,떨다', '집안에 좋지 않은 일이 생기거나 자신이 계획하던 일 또는 사업이 경영난이나 재정난을 겪게 되는 등의 좋지 않은 일이 생긴다.'),
                                                                                   ('불', '열정, 성공, 변화', '하늘,불덩이,떨어지다,불,먼곳,확산되다', '예정에 없던 갑작스럽고 막연한 여행을 하게 된다. 또한 이 여행을 통해 인생에서 새롭고 아름다운 면을 깨닫게 된다.'),
                                                                                   ('불', '열정, 성공, 변화', '하늘,불덩이,떨어지다,보다', '어떤 혁신적인 일이 생겨서 삶의 방향이나 사업 추진 중인 일의 방향을 바꾸게 될 것이다.'),
                                                                                   ('불', '열정, 성공, 변화', '화롯불,꺼지다,추위,느끼다', '추진하던 일이나 소원 노력하던 일 등이 좌절되거나 희망을 잃게 된다.'),
                                                                                   ('불', '열정, 성공, 변화', '화재,나다,불,끄지않다,도망치다', '집 안이나 직장에서 화근이 생기고 불길한 일이 생겨서 그 일로 인하여 정신적 고통을 받게 된다.'),
                                                                                   ('불', '열정, 성공, 변화', '화재,인해서,화상,입다', '행운이 찾아올 징조이다. 또는 지나친 성생활을 경고하는 꿈이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('연기', '불명확, 장애, 소식', '공장,폭발,화재,발생,연기,불꽃,타오르다', '사업의 성취와 발전을 이룩하여 부귀를 얻게 되고 재산과 명예의 융성 및 입신 출세의 성공을 획득하게 된다. 그러나 타버린 잿더미와 검은 연기만 보이고 불꽃이나 희염이 없을 경우에는 큰 파탄과 손실 말썽 불상사 등 흉험을 치르게 된다.'),
                                                                                   ('연기', '불명확, 장애, 소식', '나무나,물건,태우다,검은,연기,나다,잘,타지않다', '어떠한 장애로 인해 일이 지연되거나 침체기에 빠질 암시이다. 실력이 있어도 실력을 발휘할 수 있는 기회를 얻지 못하며 알아주는 사람이 없다.'),
                                                                                   ('연기', '불명확, 장애, 소식', '집,화재,나다,지붕,시커먼,연기,뿌옇게,솟아오르다,불꽃,전혀,보이지않다', '불꽃은 보이지 않고 불탄 흔적만 보이거나 연기만 솟아오르는 꿈은 어려운 문제가 생겨 일의 진척보다는 문제 해결에만 매달리다가 끝내 결과를 보지 못하게 될 암시이다.'),
                                                                                   ('연기', '불명확, 장애, 소식', '스스로,불,지르다,타오르다,연기,바라보다', '모든 근심 걱정이 사라지게 된다.'),
                                                                                   ('연기', '불명확, 장애, 소식', '지평선,위,검은,연기,검은,구름,피어오르다', '먼 나라 또는 훗날에 전란 등의 불길한 소식을 듣게 된다.'),
                                                                                   ('연기', '불명확, 장애, 소식', '북두칠성,자신의집,들어오다', '큰 횡재수가 있거나 관청 국가 기관 등에서 고위직에 오르게 된다. 만약 북두칠성이 자리를 바꾸는 꿈이었다면 사국이나 사회에 변화가 생긴다.'),
                                                                                   ('연기', '불명확, 장애, 소식', '하늘,샛별,반짝이다', '예술가나 연예인 등은 크게 이름을 떨칠 길몽이며 일반인들도 소원을 성취할 좋은 꿈이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('달', '여성, 풍요, 변화', '나무,걸리다,따다,집,돌아오다', '부인과 새댁은 임신을 하여 예쁜 딸을 낳는다. 횡재 재물 돈이 생긴다.'),
                                                                                   ('달', '여성, 풍요, 변화', '달나라,생각,거닐다', '소원 추진 중인 일 사업 등이 성취될 것이다. 그러나 이와 달리 별로 좋지 않은 꿈으로 해석되기도 하는데 주색에 빠질 수 있으므로 조심해야 한다.'),
                                                                                   ('달', '여성, 풍요, 변화', '달빛,받으며,거니다', '평소 그렇게 친분이 없던 사람이나 친하지 않던 친구가 찾아와 얘기를 나누게 될 것이다.'),
                                                                                   ('달', '여성, 풍요, 변화', '달빛,세상,환히,비추다', '취업을 하게 되거나 승진의 기쁨을 누리게 될 것이다. 수험생들은 시험에 합격하게 되며 사업가는 사업이 번창하여 재물을 쌓게 되는 길몽이다.'),
                                                                                   ('달', '여성, 풍요, 변화', '달빛,자신의집,비추다', '사업이나 추진 중인 일이 크게 번성할 길몽이다. 혹은 기다리던 사람에게서 좋은 소식을 듣게 된다.'),
                                                                                   ('달', '여성, 풍요, 변화', '보며,술,마시다', '사회적으로 어떤 책임질 일을 맡게 될 것이다.'),
                                                                                   ('달', '여성, 풍요, 변화', '갑자기,떨어지다', '부모님이나 남편(아내) 등 가족의 신상에 중대한 불행이 일어날 암시이다.'),
                                                                                   ('달', '여성, 풍요, 변화', '구름,반쯤,가려지다', '부부간에 오해나 다른 문제가 생겨 사이가 벌어지고 다투게 될 것을 암시한다.'),
                                                                                   ('달', '여성, 풍요, 변화', '구름,벗어나다,보다', '취직이 되지 않아 고민하던 사람은 취직이 되고 직장인은 승진을 하게 되며 사업가는 자금 사정이 풀리게 되는 등 지금까지의 근심 걱정이 사라지고 기쁜 일이 생길 것이다.'),
                                                                                   ('달', '여성, 풍요, 변화', '산너머,지다', '부모님이나 남편(아내)의 죽음을 암시하는 흉몽이다.'),
                                                                                   ('달', '여성, 풍요, 변화', '여러개,떠있다', '많은 재산이 들어오게 될 것을 암시한다.'),
                                                                                   ('달', '여성, 풍요, 변화', '달무리,지다,보다', '혼담이 성사되어 결혼으로 이어질 것이다. 미혼인 사람들이 많이 꾸게 되는 꿈이다.'),
                                                                                   ('달', '여성, 풍요, 변화', '토끼,떡방아,찧다', '집안이 안정 반성하고 미혼자는 혼사의 성취나 귀인을 상봉하게 되며 기혼자는 귀여운 자녀를 잉태하게 된다.'),
                                                                                   ('달', '여성, 풍요, 변화', '보름달,바라보다', '자신이 원하는 대로 일의 조건이나 환경을 손에 넣을 수 있고 만사가 호전될 징조.'),
                                                                                   ('달', '여성, 풍요, 변화', '수면위,그림자,비치다', '계획한 일이 뜻대로 되지 않는다는 것을 암시한다. 혼담이 깨지거나 계약이 파기되며 기대를 걸었던 일이 중도에서 좌절된다.'),
                                                                                   ('달', '여성, 풍요, 변화', '자신,향해,절,하다', '높은 신분을 지닌 사람이나 윗사람 등에게 자신의 뜻이 관철되어 어떤 일을 추진하게 될 것이다.'),
                                                                                   ('달', '여성, 풍요, 변화', '초승달,점점,둥글어지다', '사업 예술 추진 중인 일 등이 점차 크게 발전하게 될 것을 예시한다. 또한 직장인은 단계를 밟아 순조롭게 승진을 하게 되며 학생은 점차 성적이 올라간다.'),
                                                                                   ('달', '여성, 풍요, 변화', '창문,달빛,들어와,방안,대낮처럼,밝다', '집안에 경사스러운 일이 발생할 징조. 행운의 신이 찾아올 길몽이다.'),
                                                                                   ('달', '여성, 풍요, 변화', '하늘,떨어지다,굴러,뱃속,들다', '장차 사회사업이나 계몽적인 사업 어떤 지도자적인 권리를 가질 큰 인물이 될 것이다.'),
                                                                                   ('달', '여성, 풍요, 변화', '활,쏘다,맞추다', '경쟁자를 물리치고 승리하게 된다.'),
                                                                                   ('달', '여성, 풍요, 변화', '하늘,해,달,함께,떠있다', '하늘에 나란히 떠 있는 해와 달은 부모님을 암시한다. 꿈속의 해와 달의 빛이 밝고 환하다고 느꼈다면 명예가 상승하고 사업이 번창하게 되는 길몽이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('별', '희망, 명예, 운명', '떨어지다,용마루,구르다', '사업이나 추진하던 일이 크게 성공하고 학문적으로도 큰 업적을 쌓게 된다. 예술가라면 훌륭한 작품을 내 크게 명성을 얻고 부귀로워진다.'),
                                                                                   ('별', '희망, 명예, 운명', '밤하늘,무수히,많다,유난히,반짝이다', '하는 일마다 만사형통하며 많은 사람들로부터 인정을 받게 된다.'),
                                                                                   ('별', '희망, 명예, 운명', '하나,하늘,가로질러,움직이다', '직장을 옮기거나 이사를 하는 등 환경의 변화를 암시한다.'),
                                                                                   ('별', '희망, 명예, 운명', '낙엽,땅,떨어지다,보다', '사업상 손해를 입게 된다. 뭔가 큰 변화를 도모하지 않으면 손해가 점점 늘어나게 된다.'),
                                                                                   ('별', '희망, 명예, 운명', '별무리,줄지어,있다,보다', '연예인이나 예술가들이라면 자신을 좋아하는 팬들이 많이 생기게 되며 자신의 추종자나 부하들이 늘어날 것이다. 일반인이라면 점차 재물이 쌓이게 된다.'),
                                                                                   ('별', '희망, 명예, 운명', '날아다니다', '배우자나 애인이 바람을 피운다.'),
                                                                                   ('별', '희망, 명예, 운명', '땅,떨어지다', '일반적으로 하늘에 있는 별이 땅에 떨어지는 것은 권력자나 세력가 등의 유명인의 사망이나 몰락 하야 등을 예시한다.'),
                                                                                   ('별', '희망, 명예, 운명', '방향,옮겨,가다,보다', '사업장을 옮기거나 이사할 일이 생긴다.'),
                                                                                   ('별', '희망, 명예, 운명', '일제히,땅,떨어지다,사방,흩어지다', '예로부터 별이 떨어지는 꿈은 천재지변이나 전쟁 등으로 해석했다. 개인적으로는 자기 것이 될 번했던 재물을 놓치거나 그동안 모은 재물을 잃게 되며 자기를 도와주던 사람이 떠나게 된다.'),
                                                                                   ('별', '희망, 명예, 운명', '커지다', '작은 사업이 크게 번창하거나 작게 시작한 일이 점점 번성해진다.'),
                                                                                   ('별', '희망, 명예, 운명', '북두칠성,선명하게,기억,남다', '높은 지위에 오르고 명예를 얻을 길몽이다.'),
                                                                                   ('별', '희망, 명예, 운명', '북두칠성,자신의집,들어오다', '큰 횡재수가 있거나 관청 국가 기관 등에서 고위직에 오르게 된다.'),
                                                                                   ('별', '희망, 명예, 운명', '하늘,샛별,반짝이다', '예술가나 연예인 등은 크게 이름을 떨칠 길몽이며 일반인들도 소원을 성취할 좋은 꿈이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('비', '정화, 풍요, 감정', '갑자기,내리다,소나기,개미떼,물살,떠내려가다', '순간의 실수로 인해 사고가 나고 많은 재산과 인명 피해가 있을 것을 예고하는 흉몽.'),
                                                                                   ('비', '정화, 풍요, 감정', '강가,조약돌,위,내리다,보다', '자신의 작품이 사람들에게 평가받게 되며 많은 사람들이 자신의 선행이나 업적을 높이 평가하여 칭송하게 된다.'),
                                                                                   ('비', '정화, 풍요, 감정', '곡식,고추,말리다,넘어놓다,갑자기,쏟아지다', '남에게 돈을 빌려주거나 보증을 서준 것이 잘못되어 손해를 입게 될 암시이다.'),
                                                                                   ('비', '정화, 풍요, 감정', '길,걷다,갑자기,맞다', '뜻하지 않게 누군가로부터 돈을 얻게 되거나 음식물을 대접받을 일이 생긴다.'),
                                                                                   ('비', '정화, 풍요, 감정', '보슬비,맞으며,걷다', '어떤 문제에 부딪쳐 어려움을 겪고 있다. 해결 방법을 찾지 못해 절망감에 빠져 있는 상태이다.'),
                                                                                   ('비', '정화, 풍요, 감정', '오는날,버섯,뭉게뭉게,자라나다', '사회적으로 혹은 주위 환경의 도움으로 사업이나 추진하던 일 학문 등의 일이 성장하여 재물을 쌓게 되는 것을 예시한다.'),
                                                                                   ('비', '정화, 풍요, 감정', '내리다,우산,없다,난감하다', '좋지 않은 일로 이사하게 될 암시이다. 금전적인 문제 때문에 집을 줄여서 이사하게 되거나 다른 어떤 문제로 인해 어쩔 수 없이 현재 살고 있는 집에서 떠나게 될 꿈이다.'),
                                                                                   ('비', '정화, 풍요, 감정', '오다,천장,새다', '고민이나 근심 걱정거리가 생기고 사업이 흔들리게 될 것이다. 혹은 어떤 비밀이 누설되고 다른 사람의 고민거리를 해결해주어야 할 일이 생길 것이다.'),
                                                                                   ('비', '정화, 풍요, 감정', '와서,홍수,나다', '구설수에 오르게 되거나 일이 뜻대로 잘 되지 않을 재수 없는 꿈이다.'),
                                                                                   ('비', '정화, 풍요, 감정', '창문,들이치다,보다', '사업이나 추진 중인 일 연구 작품 등이 좋은 평가를 받게 되어 명예를 얻게 된다.'),
                                                                                   ('비', '정화, 풍요, 감정', '맞으며,뛰다,적당한,장소,발견,피하다', '문제에 부딪치긴 했지만 아예 막막한 상황은 아니다. 어느 정도 시간이 지나고 나면 문제가 해결되고 원하는 바를 성취할 수 있게 된다.'),
                                                                                   ('비', '정화, 풍요, 감정', '빗속,우산,들고,누군가,마중,나가다,기다리다', '꿈속에서 기다리던 그 사람이 현재 어떤 일로 어려움을 겪고 있어서 걱정하는 마음이 꿈에 나타난 것이다.'),
                                                                                   ('비', '정화, 풍요, 감정', '사방,물,잠기다,비,그치지않다,걱정하다', '집안에 흉사가 있거나 사회적으로 어떤 환난이 닥칠 것을 암시하는 꿈이다.'),
                                                                                   ('비', '정화, 풍요, 감정', '소나기,온몸,흠뻑,젖다', '누군가로부터 큰 도움을 받게 되거나 큰 은혜를 받게 된다.'),
                                                                                   ('비', '정화, 풍요, 감정', '소나기,맞으며,시원함,느끼다', '금전상으로 큰 이득을 얻게 될 암시이다. 누군가의 도움 또는 운세의 도움으로 어려움이 시원하게 해결되고 성공을 거두게 된다.'),
                                                                                   ('비', '정화, 풍요, 감정', '빗방울,한두방울,떨어지다', '눈물과 슬픔 불만이나 불쾌감 등을 체험하게 될 것을 암시한다.'),
                                                                                   ('비', '정화, 풍요, 감정', '피하다,처마,밑,들어가다', '사회적인 자극을 피할 일이 생기며 모처럼의 행운을 얻지 못하고 남에게 의지해서 사업의 명맥을 유지하게 된다.'),
                                                                                   ('비', '정화, 풍요, 감정', '장대비,내리다,한치앞,보이지않다', '뜻하지 않은 문제에 부딪혀 해결 방법이나 자신의 미래가 한치 앞도 보이지 않는 막막한 상황이 그대로 꿈에 나타난 것이다.'),
                                                                                   ('비', '정화, 풍요, 감정', '창문,굵은,빗방울,들이치다', '많은 사람들에게 자신의 실력을 인정받게 된다.'),
                                                                                   ('비', '정화, 풍요, 감정', '하늘,해,뜨다,비,내리다', '곤란과 장애에 부딪쳐 갈등과 방황을 겪게 되며 부부 또는 연인 사이에 애정의 풍파나 말썽이 생기게 된다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('눈', '순수, 정화, 시련', '가족,친구,가까운사람,눈,잔뜩,맞으며,걷다', '그 사람에게 좋지 않은 일이 생기게 될 징조이다. 사고나 질병으로 건강을 잃게 되거나 복잡한 일에 연루되어 곤욕을 치를 조짐이다.'),
                                                                                   ('눈', '순수, 정화, 시련', '눈덮이다,산,오르다', '어떤 일이나 학문 신앙 등의 난관을 극복하게 될 것이다.'),
                                                                                   ('눈', '순수, 정화, 시련', '자신,스스로,눈,모,심다', '멀리 길을 떠나게 될 것을 암시한다.'),
                                                                                   ('눈', '순수, 정화, 시련', '잡초,무성,논이나,밭,서있다', '열심히 일을 해도 아무런 성과가 없거나 살속이 없어서 허탈하게 될 암시이다.'),
                                                                                   ('눈', '순수, 정화, 시련', '쌓인길,빙판,얼어있다', '자신의 마음이 싸늘하게 식어 있음을 암시하는 꿈이다. 사랑하는 사람에게서 마음이 떠나 있다.'),
                                                                                   ('눈', '순수, 정화, 시련', '쌓인,설원,스키,타다,썰매,타다', '사업가라면 사업이 급속도로 성장하게 되고 취직 시험 등에 무난히 통과하게 된다.'),
                                                                                   ('눈', '순수, 정화, 시련', '눈과,비,섞여,내리다', '가까운 사람에게 배반당하거나 사기를 당하거나 방해를 받을 우려가 있다.'),
                                                                                   ('눈', '순수, 정화, 시련', '눈발,거세게,바람,날리다', '뜻밖의 횡재를 하게 될 꿈이다.'),
                                                                                   ('눈', '순수, 정화, 시련', '눈,맞다', '사업 추진 중인 일이 순조롭게 진행되어 갈 것이다.'),
                                                                                   ('눈', '순수, 정화, 시련', '녹다,사방,질퍽하게,보이다', '시비가 생겨 해결을 보지 못하며 일 처리가 매끄럽지 못할 것이다.'),
                                                                                   ('눈', '순수, 정화, 시련', '소담스럽게,내리다,소복소복,쌓이다,보다', '사회적으로 큰 일을 도모할 수 있는 시기가 도래했음을 알려주는 꿈이다. 행복한 결혼 등 새 생활의 즐거운 변화가 찾아오게 될 암시이며 이밖에도 현재보다 나은 새로운 환경에서 생활하게 될 것을 예시한다.'),
                                                                                   ('눈', '순수, 정화, 시련', '쌓이다,쓸어버리다', '자신에게 다가온 좋은 기회를 놓쳐버리게 된다.'),
                                                                                   ('눈', '순수, 정화, 시련', '오다가,비,오다가,우박,오다,변화무쌍하다', '걱정할 일이 자주 생기고 장애와 곤란이 생기거나 일이 뜻대로 풀리지 않아 몸과 마음이 피곤하게 된다.'),
                                                                                   ('눈', '순수, 정화, 시련', '눈사람,만들다,눈,크게,뭉쳐,눈싸움,하다', '사업적으로나 가정적으로 큰 재산을 축적하게 된다.'),
                                                                                   ('눈', '순수, 정화, 시련', '눈사태,길,막히다,오도가도못하다', '동기간에 의를 상할 일이 생길 암시이다. 또는 뜻밖의 재난으로 가족들이 뿔뿔이 흩어지거나 어려움을 겪게 될 암시이다.'),
                                                                                   ('눈', '순수, 정화, 시련', '눈사태,집,한쪽,귀퉁이,무너져내리다', '사업상 악재가 겹쳐 어려움을 겪게 될 징조이다.'),
                                                                                   ('눈', '순수, 정화, 시련', '마당,덮이다,눈,비로,쓸다', '오랫동안 잘 풀리지 않거나 유보상태에 있던 어떤 일이 잘 풀리며 사업이나 계획하던 일이 잘 성취될 것이다. 혹은 자기의 세력을 가질 수 있게 된다.'),
                                                                                   ('눈', '순수, 정화, 시련', '사방,어두컴컴,음산하게,눈,내리다', '불행한 일이 닥쳐올 것을 암시하는 흉몽이다.'),
                                                                                   ('눈', '순수, 정화, 시련', '싸락눈,내리다,보다', '추진 중인 일이 노력의 보람도 없이 하무하게 끝나게 된다. 혹은 어떤 소문에 휩싸이거나 시끄러운 일이 생기게 된다.'),
                                                                                   ('눈', '순수, 정화, 시련', '엄청난,폭설,건물,집,내려앉다', '국가적 사체이나 사회적인 분위기가 자신이 하고 있는 일에 유리하게 돌아갈 암시이다.'),
                                                                                   ('눈', '순수, 정화, 시련', '온천지,새하얀,눈,뒤덮다,평화롭게,보이다', '운세가 호전될 꿈이다. 학문이나 연구를 하는 사람이라면 큰 성과와 업적을 내게 되고 정치가나 사업가라면 도약의 기회를 만나게 된다.'),
                                                                                   ('눈', '순수, 정화, 시련', '춥고,답답한,골목,우울하게,싸라기눈,내리다,보다', '별 소득이 없는 일에 시간과 노력을 쏟고 있다는 것을 알려주는 꿈이다. 아무 이득도 없이 마음만 삼난해지게 된다.'),
                                                                                   ('눈', '순수, 정화, 시련', '주먹만한,눈송이,집,쏟아져,들어오다', '집 안에 보탬이 될만한 무언가가 들어오게 될 것이다. 그것이 재물이거나 일거리거나 사람이 될 수 있다.'),
                                                                                   ('눈', '순수, 정화, 시련', '크다,탐스럽다,눈송이,방,내려,쌓이다', '재물이 들어와 쌓이게 된다. 특히 사례금이나 청탁 등을 받게 된다.'),
                                                                                   ('눈', '순수, 정화, 시련', '하얀눈,위,발자국,나있다,따라가다', '사회적으로 유명한 인물이나 고위직에 있는 사람의 수하에 들어가게 될 암시이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('번개', '갑작스러운 변화, 깨달음, 영감', '번개,피하다,벼락,땅,건물,부딪치다,치솟다', '번개를 피하거나 벼락이 땅이나 건물에 부딪쳐 치솟는 꿈은 간신히 명예를 얻거나 자신의 생명을 보존하는 뜻이다.'),
                                                                                   ('번개', '갑작스러운 변화, 깨달음, 영감', '우레,울리다,번개,치다', '우레기 울리고 번개가 친 꿈은 충격적인 일을 당하지만 좋은 결과를 얻게 된다.'),
                                                                                   ('번개', '갑작스러운 변화, 깨달음, 영감', '하늘,먹구름,끼다,번개,번쩍이다', '하늘에 먹구름이 끼고 번개가 번쩍이는 꿈은 어려운 상황이 닥치지만 이를 극복할 힘이 생김을 의미한다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('벼락', '충격, 권력, 천벌', '벼락,맞다,치다', '벼락 맞거나 치는 꿈은 권위자나 상급 기관에서 압력을 받거나 견책 받는 일이 생긴다.'),
                                                                                   ('벼락', '충격, 권력, 천벌', '하늘,마른벼락,치다', '맑은 하늘에서 마른벼락 치던 꿈은 국가적으로 큰 사건이나 큰 변화가 일어난다.'),
                                                                                   ('벼락', '충격, 권력, 천벌', '번개,상위,내리치다', '번개가 상위에 내리친 꿈은 장차 크게 성공하여 권세와 명예를 널리 과시할 인물이 될 것이다. 또한 어떤 일이 외국까지 명성을 떨치게 될 것이며 이를 통해 인생의 전환점을 맞게 된다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('서리', '시련, 냉정함, 정화', '서리,끼다,샘물,금고', '서리가 낀 샘물종이 금고 이끓다운 꿈은 권력을 얻게 되며 성과가 생긴다.'),
                                                                                   ('서리', '시련, 냉정함, 정화', '서리,내리다,하얗다', '서리가 내려 주위가 하얗게 되었다는 꿈은 사업이 크게 어려워져 더 이상 버텨낼 수 없게 됨을 암시한다.'),
                                                                                   ('서리', '시련, 냉정함, 정화', '옷,물건,이슬,서리,내리다', '자기 옷이나 물건에 이슬이나 서리가 내린 꿈은 원하는 바를 이루지 못하고 마음고생을 하게 될 일이 생긴다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('태양', '권력, 성공, 명예, 지도자', '태양,사라지다', '감자기 태양이 사라져버린 꿈은 가정에 우환이 생기거나 사업이 망하거나 근심걱정거리가 생긴다.'),
                                                                                   ('태양', '권력, 성공, 명예, 지도자', '태양,빛,잃다', '빛을 잃은 태양을 본 꿈은 불길한 사건이 발생할 조짐이다.'),
                                                                                   ('태양', '권력, 성공, 명예, 지도자', '해,동쪽,떠오르다,붉다,빛나다', '해가 동쪽서 떠오르며 붉게 빛나는 꿈은 장차 사회적인 사업과 영향적인 시범을 가져올 인물이 될 것이다.'),
                                                                                   ('태양', '권력, 성공, 명예, 지도자', '해,하늘,한복판,떠,있다', '해가 하늘 한복판에 떠 있는 것을 보는 꿈은 시름끼지의 근심, 걱정이 사라지고 만사 형통할 길몽이다. 진행중인 일이 원만하게 성취된다.'),
                                                                                   ('태양', '권력, 성공, 명예, 지도자', '해,희미하다,구름,가리다', '해가 희미하고 구름에 가리는 꿈은 뜻하는 크지만 근심에 치장는 사람이나 기업체를 암시할 길몽이기 무언가를 계획하고 짐작 에서서 오는 자신도 이행게 부담감을 느끼게 될 길몽이다.'),
                                                                                   ('태양', '권력, 성공, 명예, 지도자', '해,보다,품,들어가다', '해를 보아 가지고 품으로 들어가는 꿈은 천부적 힘줄을 얻게 길몽이다. 잠재 정산가 겸장 길몽이다. 사업적으로도 운이한 임을 생사시거에 되며 직장에서 요즘게 된다.'),
                                                                                   ('태양', '권력, 성공, 명예, 지도자', '바다,해,떠오르다', '바다에서 해가 떠오르는 것을 보는 꿈은 자습이 빚장하고 장할 품이다. 잠 언에 경사가 겸장 길몽이다. 사업적으로도 운이한 임을 생사시거에 되며 직장에서 요즘게 된다.'),
                                                                                   ('태양', '권력, 성공, 명예, 지도자', '해,뜨다', '해가 뜨는 꿈은 대운으로 그 이가는 장차 해당을 그고 공정 보거는 권세나 명예, 업적 등을 이룰 것이다.'),
                                                                                   ('태양', '권력, 성공, 명예, 지도자', '해,떠,있다,비,나타나다', '해가 떠 있는 가운데 비가 나타는 꿈은 생사의 일이라던 대까가 조정가나 사건을 간다는 표현을 한다. 그러나 꿈의 해몽이 배우지와 그래 나뜨게나 변인 과 써위서 도문간 사이이가 좋지 않을 정조이다.'),
                                                                                   ('태양', '권력, 성공, 명예, 지도자', '해,떨어지다,구름,보다', '해가 떨어져 구름가나 해를 보는 꿈은 해가 혼어졌어나 구름는 것을 보면 장차 그 데로느 사회나 국가적으로 훌륭한 연모을 낳거거나 우레한 통의 정상이 그 오래되 되는 좋은 의미 세가 좋다 되는 것이다.'),
                                                                                   ('태양', '권력, 성공, 명예, 지도자', '해,반,갈라지다', '해가 반으로 갈라지는 것을 본 꿈은 잠 언에 불화가 생길까 단사가 이진미이가 발동이가 림다.'),
                                                                                   ('태양', '권력, 성공, 명예, 지도자', '해,지다,석양,바라보다', '해가 지는 광경, 즉 석양을 바라보는 꿈은 운세가 극도로 쇠퇴되고 있다는 암시이다. 업무상 시련 발명에서 좌절을 겪을 암시이며 별이 주의하라는 경고이다.'),
                                                                                   ('태양', '권력, 성공, 명예, 지도자', '해,손,떠,가지다', '해를 손으로 떠 가지는 꿈은 그게는 국가 권세나 치권는 사회적인 기업체를 암시할 길몽이기 무언가를 예시한다.'),
                                                                                   ('태양', '권력, 성공, 명예, 지도자', '해,향하다,절,하다', '해를 향해 절을 하는 꿈은 국가 기관에 부득할 일이 생기거나 그 부뚝이 변이들어져 어떤 이득을 얻게 된다.'),
                                                                                   ('태양', '권력, 성공, 명예, 지도자', '해,달,나란히,하늘,떠,있다', '해와 달이 나란히 하늘에 떠 있는 꿈은 나뭇잎 떠 있는 해와 달은 무두극을 상징한다. 그 해와 달의 빛으로 주위가 더욱 한해겼다면 부부극의 곤란의 후 광으로 지신의 명성이 명일 길몽이자만 반대로 불길다다는 노김은 반짝 뿌며 부두극의 사례에 문제가 생길 가능성이 있다.'),
                                                                                   ('태양', '권력, 성공, 명예, 지도자', '해,가슴,안다', '해를 가슴에 안고 있는 꿈은 사업가는 사업에 성공하고, 선부선녀는 사업의 업체를 팔게 될 정조이다. 임신, 상, 훈장, 자격증, 권세, 승진, 당선, 합격, 관계 등과 관계가 있다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('구름', '불안, 장애, 변화', '구름,도라이,로,흥겹다,피어오르다', '엄청난 서류, 고서, 취직 서류이 많격하게 띠거나 신께 출가할 사람이나 후진을 통이 건강이 세상에 드러나 극려할 승진을 하게 된다.'),
                                                                                   ('구름', '불안, 장애, 변화', '구름,모래,용재출게,피어오르다', '구름이 모대으로 용재출게 피어오르는 것을 보는 꿈은 입학이 속출하여 집 안에 경사가 겸진 길몽이다.'),
                                                                                   ('구름', '불안, 장애, 변화', '구름,갑맸,가리다', '구름이 갑맸을 가린 꿈은 남의 비말을 들게 된다.'),
                                                                                   ('구름', '불안, 장애, 변화', '구름,인개,자신,감싸다', '구름이나 안개가 자신을 감싸는 꿈은 누군가 자신의 약점이나 취한 점솔가니 비밀 동을 갈려주기나 추적하는 사람이 그래 건상하고 직장상의 승진을 하게 된다.'),
                                                                                   ('구름', '불안, 장애, 변화', '바랑기,먹구름,속,사라지다', '바랑기가 먹구름 속으로 사라진 꿈은 남의 터뚜이나 사람으로 자기의 생사이 확롭되고 진행 증인 일에나 확생을 암시하는 것이 겸이다.'),
                                                                                   ('구름', '불안, 장애, 변화', '사랑,구름,용재출게,피어오르다', '사랑와서 한 구름이 용재출게 피어오르는 것을 보는 꿈은 계임이나 상업 등이 잘 이루어지지니 걸사나 장사, 흉정 등이 매우 잘 이루어지게 된다. 또한 대인관계에서 잘은 이미 게생이고 구르는 것이 일어나 새게에 퍼지가나 전공하게 된다.'),
                                                                                   ('구름', '불안, 장애, 변화', '오색,찬란,구름', '오색전한 구름을 본 꿈은 수습은 시법들에게서 인기를 한 동안 있었바 권면 거이다.'),
                                                                                   ('구름', '불안, 장애, 변화', '구름,사람,용재출게,피어오르다', '한 구름이 사람으로 용재출게 피어오르는 꿈은 사업이 크게 일어나나 공구에 나가거나 흘미하고 신는 게세이가 일어나게 된다.'),
                                                                                   ('구름', '불안, 장애, 변화', '한몽개,구름,흘어지다', '한몽개구름이 흘어지는 꿈은 사업이 그래 일어나나 난리가 생기거나 공는에 나가거 겸이다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('하늘', '이상, 목표, 권위', '하늘,갈라지다', '하늘이 갈라지는 꿈은 큰 재난이 닿아을 것을 암시하는 것이다.'),
                                                                                   ('하늘', '이상, 목표, 권위', '하늘,무너지다,쏟아지다', '하늘이 무너져 쏟아를 내려 무너지는 꿈은 가정에 슬픈 일이나 재난이 닥칠 징조이다.'),
                                                                                   ('하늘', '이상, 목표, 권위', '하늘,새벽간', '하늘이 새벽간 꿈은 놀라 다곳조 새개가 임혀 있던 것을 의미한다.'),
                                                                                   ('하늘', '이상, 목표, 권위', '하늘,황색,염려', '하늘이 황색 염려는 꿈은 국가나 사회에 혼란 등 변고가 일어나게 된다.'),
                                                                                   ('하늘', '이상, 목표, 권위', '하늘,해,달,동시,떠오르다', '하늘에 해와 달이 동시에 떠오는는 꿈은 자신의 사업이나 사업에 제2의 인물이 나타나 도움을 받거나 협조를 얻게 될 것이다. 또한 인간관계에서 새에 있어서나 주변에서 도움을 주는 사람이 드테나거나 새로 사로일 인물이 생기게 된다.'),
                                                                                   ('하늘', '이상, 목표, 권위', '하늘,낮,올라가다,떨어지다', '하늘는 낮이 올라간다 떨어지는 꿈은 구상하는 일이 순조롭게 잘 진도가가 나아가져 못하고 중간에서 좌절되는 것을 암시한다.'),
                                                                                   ('하늘', '이상, 목표, 권위', '하늘,낯은,꿈,떨어지다', '하늘에서 낯은 꿈으로 떨어지는 꿈은 어린이나 들라이라면 성장이 삼성하고 자부블 삼성하고 직장상 일찬을 얻게 될 것이다.'),
                                                                                   ('하늘', '이상, 목표, 권위', '하늘,쏟아,무너지다', '하늘이 쏟아와 무너지는 꿈은 여린이나 본라이라면 성정이 삼정하여 짖장상 직장이 일어나 새계에 이르게 되는 일이 앙습니다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('바람', '변화, 소문, 영향력', '강한,바람,정면,맞다,넘어지다,않다', '강한 바람이 정면으로 맞으면서도 사랑이 넘어지지 않짝던 꿈은 주변의 모든 근심 걱정이 싹쓸 두 사라지거 됨 것이다. 경제적으로 어려움을 겪고 있다면 사터에서 물러나고도 뛰게가 없뜨라 차초 생명이 있을 사터이면라도 저조를 회복하게 될 것이다.'),
                                                                                   ('바람', '변화, 소문, 영향력', '돗,명인,신로,오다', '도 면인 신로 오는는 꿈은 어떤 일이나 작품이 더판대일 만큼 받곳 다다 몇 자치에게 된 읍실로움이 생기하고나 선부센녀는 사업의 업체를 팔게 될 정조이다.'),
                                                                                   ('바람', '변화, 소문, 영향력', '바람,타다,날아가다', '바람을 타고 날아가는 꿈은 타인이 반할 일로콘 양매회 됨이 잠기거나 인전으이가 되각된 꿈이다.'),
                                                                                   ('바람', '변화, 소문, 영향력', '자기,집,입구,주사,있다,바람,불어오다,냄새,나다', '자기 집 입구에 주사 있다 바람이 불어오는데 냄새가 나던 꿈은 어떤 일의 짚대인 대폭에 이등의한 진조.'),
                                                                                   ('바람', '변화, 소문, 영향력', '차가,집,입구,주자,바람,냄새', '차가 집 입구에 주자 바람에 냄새를 느낀 꿈은 집 언에 변할 일무일 있었던 신조 살며시 됩니다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('무지개', '희망, 행운, 다리', '무지개,감기,붙을,얻다,중건,경앗치다', '기대했던 일이 중도에 깨앗지거나 악속이 취다되는 등 좌절이 생사되거나 무언가를 몸아야 할 상황에 치하게 된다.'),
                                                                                   ('무지개', '희망, 행운, 다리', '무지개,자기,집,무앗치다,걸리다', '집 언에 잇산 영앙하여 이음을 멀첫 자신이 태앙이 상먀러와 갈정이 호에 동아 닐 것이다.'),
                                                                                   ('무지개', '희망, 행운, 다리', '비,온,뒤,오삭,찬란,무지개,걸치다', '자신의 사업이나 사일이 더 사람 깨명을 받거나 끼인이나 닐에 용이이나 제당한 기운으로서 무언한 관문을 하게 된다. 또 한 관문이나 해앳는 는강이 쓸공저 도여 관근은 성행하게 된다.');
INSERT INTO dream_symbol_entity (keyword, meaning, situation, meaning_context) VALUES
                                                                                   ('노을', '성취, 인연, 전환점', '저녁,노을,보다', '저녁 노을을 보는 꿈은 말년에 큰 업적을 남길 사람과 관계를 맺을 징조를 나타낸다. 중요한 인연이나 기회를 만나게 될 것을 시사하며 앞으로의 성공과 성취를 예고한다.'),
                                                                                   ('노을', '성취, 인연, 전환점', '붉다,노을,하늘,물들다', '붉은 노을이 하늘을 물들인 모습을 보는 꿈은 인생의 중요한 전환점을 나타낸다. 대기만성하여 인생의 말년에 커다란 업적을 남기게 될 것을 의미한다.'),
                                                                                   ('노을', '성취, 인연, 전환점', '아침,노을,보다', '아침 노을을 보는 꿈은 새로운 시작과 희망을 상징한다. 긍정적인 변화가 시작되며 중요한 기회를 맞이하게 될 징조이다.'),
                                                                                   ('노을', '성취, 인연, 전환점', '노을,지다,바라보다', '노을이 지는 모습을 바라보는 꿈은 미래를 준비하는 시점을 상징한다. 현재의 성취를 위해 준비하고 있으며 말년에 큰 업적을 남길 사람과의 관계를 준비하고 있을 수 있다.'),
                                                                                   ('노을', '성취, 인연, 전환점', '노을,아름답다,감상하다', '아름다운 노을을 감상하는 꿈은 긍정적인 변화와 희망적인 시기를 상징한다. 당신의 인생에 긍정적인 변화를 가져올 중요한 관계나 사건이 다가오고 있음을 나타낸다.');
